// Phone and small-tablet layout. Most screens use inline grid/flex styles, so
// these rules restack them under 760px wide without changing the desktop look.
const MOBILE_CSS = `
@media (max-width: 760px) {
  html, body { overflow-x: hidden; }
  [style*="grid-template-columns: repeat(6"], [style*="grid-template-columns: repeat(5"], [style*="grid-template-columns: repeat(4"],
  [style*="grid-template-columns: repeat(3"], [style*="grid-template-columns: 1fr 1fr 1fr 1fr"], [style*="grid-template-columns: 1fr 1fr 1fr;"] {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
  [style*="grid-template-columns: 1fr 1fr;"], [style*="grid-template-columns: repeat(2"], [style*="grid-template-columns: 1.3fr 1fr"],
  [style*="grid-template-columns: 1.1fr 0.9fr"], [style*="grid-template-columns: 1.2fr 1.2fr 0.6fr 1.4fr auto"] {
    grid-template-columns: minmax(0, 1fr) !important;
  }
  [style*="display: flex"][style*="justify-content: space-between"] { flex-wrap: wrap; row-gap: 8px; }
  [style*="width: 560px"], [style*="width: 580px"], [style*="width: 520px"], [style*="width: 480px"], [style*="width: 460px"] { width: 100% !important; }
  [style*="padding: 24px; display: flex; align-items: center; justify-content: center"] { padding: 10px !important; }
  [style*="max-height: 88vh"] { max-height: 94vh !important; }
  input, select, textarea { font-size: 16px !important; min-width: 0; max-width: 100%; }
  button { min-height: 36px; }
  .icon-btn { height: 40px !important; padding: 0 12px !important; }
  [style*="font-size: 10px"], [style*="font-size: 10.5px"], [style*="font-size: 11px"] { font-size: 12px !important; }
  [style*="font-size: 11.5px"], [style*="font-size: 12px"] { font-size: 13px !important; }
  [style*="font-size: 12.5px"], [style*="font-size: 13px"] { font-size: 14px !important; }
  .quick-grid { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
  .wrap-mobile { flex-wrap: wrap !important; }
  .alaga-main { padding: 16px 14px 80px !important; }
}
@media (max-width: 420px) {
  [style*="font-size: 28px"] { font-size: 23px !important; }
}
`;
const FONTS_BASE = `
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700;9..144,900&family=Work+Sans:wght@400;500;600;700&display=swap');

/* Number inputs across the app (budgets, rates, fees, etc.) rely on typing a value
   directly rather than the tiny native up/down spinner — hide the spinner so the
   text field itself reads as the primary way to edit, on every browser engine. */
input[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}
input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
`;
const FONTS = FONTS_BASE + MOBILE_CSS + `
.icon-btn-label { display: none; }
@media (max-width: 760px) { .icon-btn-label { display: inline; } }
`;

/* ------------------------------ brand marks ---------------------------------- */
// The real, finalized Alaga logo mark — arch with batok-pattern trim, sampaguita
// flower, and gold diamond accent — embedded as a data URI so the whole app stays a
// single self-contained file. This is a fixed-color raster image now (traced from the
// actual brand asset), not a recolorable line-drawing, so `color` no longer changes its
// ink color — the prop stays only so every existing call site keeps working unchanged.
const ALAGA_LOGO_SRC = "data:image/png;base64,";
function AlagaMark({ size = 20, color = "#fff", arch = true, backdrop = true }) {
  // On dark backgrounds (sidebar, admin header, parent app header) the mark's own dark
  // green linework would disappear, so we drop a soft light backdrop behind it there.
  const isDarkContext = backdrop && (color === "#fff" || color === "#EFEAE0");
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      width: size, height: size * 1.29,
      background: isDarkContext ? "rgba(255,255,255,0.92)" : "transparent",
      borderRadius: isDarkContext ? size * 0.16 : 0,
      padding: isDarkContext ? size * 0.09 : 0,
      boxSizing: "border-box",
      flexShrink: 0,
    }}>
      <img src={ALAGA_LOGO_SRC} alt="Alaga" width="100%" height="100%" style={{ objectFit: "contain", display: "block" }} />
    </span>
  );
}

// A banig-weave texture (the woven-mat pattern common in Filipino textiles), rendered as
// a small tileable SVG data URI so it can drop straight into a CSS background-image.
const BANIG_PATTERN = (color, opacity = 1) => {
  const c = encodeURIComponent(color);
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16'><g fill='none' stroke='${c}' stroke-width='1' opacity='${opacity}'><path d='M0 4 L16 4 M0 12 L16 12'/><path d='M4 0 L4 16 M12 0 L12 16'/></g></svg>`;
  return `url("data:image/svg+xml,${svg}")`;
};

// A simple drawn "empty basket with a sampaguita sprig" — used across empty states in
// place of a generic icon-in-a-dashed-box, so a repeated pattern reads as designed.
function EmptyIllustration({ size = 76 }) {
  const petals = [0, 72, 144, 216, 288];
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" fill="none" aria-hidden="true">
      <path d="M20 46 L28 78 L72 78 L80 46 Z" stroke={C.line} strokeWidth="2.5" fill={C.cream} />
      <path d="M18 46 L82 46" stroke={C.line} strokeWidth="2.5" />
      <path d="M30 50 L34 76 M45 50 L46 78 M55 50 L54 78 M70 50 L66 76" stroke={C.line} strokeWidth="1.3" opacity="0.7" />
      <g transform="translate(50 30)">
        {petals.map((deg) => (
          <path key={deg} d="M0 0 C -3.4 -5.4, -3.7 -12.6, 0 -19 C 3.7 -12.6, 3.4 -5.4, 0 0 Z"
            fill={C.amberTint} stroke={C.amber} strokeWidth="1" transform={`rotate(${deg})`} />
        ))}
        <circle r="1.6" fill={C.amber} />
      </g>
      <line x1="50" y1="30" x2="50" y2="44" stroke={C.amber} strokeWidth="1.3" />
    </svg>
  );
}

/* ---------------------------------- data ------------------------------------ */
// The sample daycare's data was written as of July 26, 2026. Rather than freeze
// the whole app on that day, every sample date is moved forward by however long
// it's been since then — so a subsidy that "expires in 7 days" in the sample
// still expires in 7 days, and real providers' dates are measured from today.
const startOfToday = () => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; };
const DEMO_WRITTEN_ON = new Date(2026, 6, 26);
const DEMO_SHIFT_DAYS = Math.round((startOfToday() - DEMO_WRITTEN_ON) / 86400000);
const DEMO_SHIFT_MONTHS = Math.round(DEMO_SHIFT_DAYS / 30.44);
const MONTH_FULL = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const pad2 = (n) => String(n).padStart(2, "0");
function shiftDemoString(str) {
  if (!DEMO_SHIFT_DAYS) return str;
  return str
    .replace(/(?<![\d/])(\d{2})\/(\d{2})\/(\d{4})(?![\d/])/g, (_, m, d, y) => {
      const dt = new Date(+y, +m - 1, +d + DEMO_SHIFT_DAYS);
      return `${pad2(dt.getMonth() + 1)}/${pad2(dt.getDate())}/${dt.getFullYear()}`;
    })
    .replace(/(?<![\d/])(\d{2})\/(20\d{2})(?![\d/])/g, (_, m, y) => {
      const dt = new Date(+y, +m - 1 + DEMO_SHIFT_MONTHS, 1);
      return `${pad2(dt.getMonth() + 1)}/${dt.getFullYear()}`;
    })
    .replace(new RegExp(`\\b(${MONTH_FULL.join("|")}) (20\\d{2})\\b`, "g"), (_, mName, y) => {
      const dt = new Date(+y, MONTH_FULL.indexOf(mName) + DEMO_SHIFT_MONTHS, 1);
      return `${MONTH_FULL[dt.getMonth()]} ${dt.getFullYear()}`;
    });
}
// Walks plain sample-data objects and arrays; leaves icons and other components alone.
function demoDates(value, shift = shiftDemoString) {
  if (typeof value === "string") return shift(value);
  if (Array.isArray(value)) return value.map((v) => demoDates(v, shift));
  if (value && Object.getPrototypeOf(value) === Object.prototype) {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, demoDates(v, shift)]));
  }
  return value;
}
// Sample expenses move by whole months instead, so they stay grouped in one month.
const shiftDemoMonth = (str) => str.replace(/(?<![\d/])(\d{2})\/(\d{2})\/(\d{4})(?![\d/])/g, (_, m, d, y) => {
  let dt = new Date(+y, +m - 1 + DEMO_SHIFT_MONTHS, Math.min(+d, 28));
  if (dt > startOfToday()) dt = startOfToday(); // never log a sample expense in the future
  return `${pad2(dt.getMonth() + 1)}/${pad2(dt.getDate())}/${dt.getFullYear()}`;
});
