  "Mark absent": { es: "Marcar ausente", tl: "Markahan na absent", zh: "标记缺勤", vi: "Đánh dấu vắng", ko: "결석 표시" },
  "More": { es: "Más", tl: "Iba pa", zh: "更多", vi: "Thêm", ko: "더보기" },
