// California: kindergarten when a child turns 5 on or before September 1.
function kindergartenYear(birth) {
  const d = parseAnyDate(birth);
  if (!d) return null;
  const y = d.getFullYear() + 5;
  return d <= new Date(d.getFullYear(), 8, 1) ? y : y + 1;
}
