function OnboardingWizard({ onComplete, onBack, initialEmail = "" }) {
  const [step, setStep] = useState(0);
  const [form, setForm] = useState({
    businessName: "", contactName: "", email: initialEmail, city: "",
    providerType: PROVIDER_TYPES[0], licenseNumber: "", capacity: 8,
    classrooms: [], hours: "7:00 AM – 6:00 PM", days: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"],
    language: "English", languagesOffered: ["English"], subsidyPrograms: [],
  });
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const toggleProgram = (id) => setForm((f) => ({ ...f, subsidyPrograms: f.subsidyPrograms.includes(id) ? f.subsidyPrograms.filter((p) => p !== id) : [...f.subsidyPrograms, id] }));
  const toggleClassroom = (id) => setForm((f) => ({ ...f, classrooms: f.classrooms.includes(id) ? f.classrooms.filter((c) => c !== id) : [...f.classrooms, id] }));
  const toggleLanguageOffered = (lang) => setForm((f) => ({
    ...f,
    languagesOffered: f.languagesOffered.includes(lang) ? f.languagesOffered.filter((l) => l !== lang) : [...f.languagesOffered, lang],
  }));
  const toggleDay = (d) => setForm((f) => ({ ...f, days: f.days.includes(d) ? f.days.filter((x) => x !== d) : [...f.days, d] }));

  const canNext = () => {
    if (step === 0) return form.businessName.trim() && form.contactName.trim();
    if (step === 1) return form.classrooms.length > 0;
    return true;
  };

  const finish = () => {
    onComplete({
      name: form.businessName || "New Provider",
      city: form.city || "—",
      lic: form.licenseNumber ? `FCC License #${form.licenseNumber}` : "License pending",
      providerType: form.providerType,
      capacity: form.capacity,
      classrooms: form.classrooms,
      hours: form.hours,
      days: form.days,
      language: form.language,
      languagesOffered: form.languagesOffered,
      contactName: form.contactName,
      email: form.email,
      subsidyPrograms: form.subsidyPrograms,
    });
  };

  return (
    <div style={{ minHeight: "100vh", background: C.cream, fontFamily: "'Work Sans', sans-serif", display: "flex", justifyContent: "center", padding: "40px 20px" }}>
      <style>{FONTS}</style>
      <div style={{ width: "100%", maxWidth: 560 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 22 }}>
          <button onClick={onBack} style={{ background: "none", border: "none", color: C.inkSoft, display: "flex", alignItems: "center", gap: 5, fontSize: 12.5, fontWeight: 600 }}>
            <ArrowLeft size={14} /> Back
          </button>
        </div>

        <div style={{ display: "flex", gap: 5, marginBottom: 22 }}>
          {WIZARD_STEPS.map((s, i) => (
            <div key={s} style={{ flex: 1, height: 5, borderRadius: 999, background: i <= step ? C.teal : C.line }} />
          ))}
        </div>
        <div style={{ fontSize: 11.5, fontWeight: 700, color: C.tealDark, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 6 }}>
          Step {step + 1} of {WIZARD_STEPS.length}
        </div>
        <h2 style={{ fontFamily: "'Fraunces', serif", fontSize: 24, fontWeight: 600, color: C.ink, margin: "0 0 22px" }}>{WIZARD_STEPS[step]}</h2>

        <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 16, padding: 24, display: "flex", flexDirection: "column", gap: 14 }}>
          {step === 0 && (
            <>
              <Field label="Business / provider name"><input value={form.businessName} onChange={(e) => set("businessName", e.target.value)} placeholder="e.g. Tita's Family Child Care" style={inputStyle} /></Field>
              <Field label="Your name"><input value={form.contactName} onChange={(e) => set("contactName", e.target.value)} placeholder="Your full name" style={inputStyle} /></Field>
              {initialEmail ? (
                <div style={{ fontSize: 12, color: C.inkSoft, display: "flex", alignItems: "center", gap: 6 }}>
                  <CheckCircle2 size={13} color={C.teal} /> Account created for <b style={{ color: C.ink }}>{initialEmail}</b>
                </div>
              ) : (
                <Field label="Email"><input type="email" value={form.email} onChange={(e) => set("email", e.target.value)} placeholder="you@example.com" style={inputStyle} /></Field>
              )}
              <Field label="City"><input value={form.city} onChange={(e) => set("city", e.target.value)} placeholder="e.g. Culver City, CA" style={inputStyle} /></Field>
            </>
          )}

          {step === 1 && (
            <>
              <Field label="Provider type">
                <Select value={form.providerType} onChange={(v) => setForm((f) => ({ ...f, providerType: v, capacity: CAPACITY_LIMITS[v] || f.capacity }))} options={PROVIDER_TYPES} />
              </Field>
              <Field label="License number (optional if pending)"><input value={form.licenseNumber} onChange={(e) => set("licenseNumber", e.target.value)} placeholder="e.g. 198-402-3211" style={inputStyle} /></Field>
              <Field label="Total capacity">
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <input type="number" min={1} max={CAPACITY_LIMITS[form.providerType]} value={form.capacity}
                    onChange={(e) => {
                      const limit = CAPACITY_LIMITS[form.providerType];
                      const n = Number(e.target.value);
                      set("capacity", limit ? Math.min(n, limit) : n);
                    }}
                    style={{ ...inputStyle, maxWidth: 100 }} />
                  {CAPACITY_LIMITS[form.providerType] && (
                    <span style={{ fontSize: 11.5, color: C.inkSoft }}>Up to {CAPACITY_LIMITS[form.providerType]} for this license type</span>
                  )}
                </div>
              </Field>
              <Field label="Which age groups will you care for?">
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {CLASSROOMS.map((c) => (
                    <label key={c.id} style={{ display: "flex", alignItems: "center", gap: 9, fontSize: 13, padding: "8px 10px", borderRadius: 9, border: `1px solid ${form.classrooms.includes(c.id) ? C.teal : C.line}`, background: form.classrooms.includes(c.id) ? C.tealTint : "#fff" }}>
                      <input type="checkbox" checked={form.classrooms.includes(c.id)} onChange={() => toggleClassroom(c.id)} />
                      <b>{c.label}</b> <span style={{ color: C.inkSoft }}>· {c.range}</span>
                    </label>
                  ))}
                </div>
              </Field>
              <Field label="Subsidy programs you accept (skip if private-pay only)">
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {PROGRAMS.map((p) => (
                    <button key={p.id} type="button" onClick={() => toggleProgram(p.id)} style={{
                      padding: "7px 11px", borderRadius: 999, fontSize: 12.5, fontWeight: 600,
                      border: `1px solid ${form.subsidyPrograms.includes(p.id) ? C.teal : C.line}`,
                      background: form.subsidyPrograms.includes(p.id) ? C.tealTint : "#fff",
                      color: form.subsidyPrograms.includes(p.id) ? C.tealDark : C.inkSoft,
                    }}>{p.label}</button>
                  ))}
                </div>
              </Field>
            </>
          )}

          {step === 2 && (
            <>
              <Field label="Typical daily hours"><input value={form.hours} onChange={(e) => set("hours", e.target.value)} style={inputStyle} /></Field>
              <Field label="Days open">
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {ALL_DAYS.map((d) => (
                    <button key={d} onClick={() => toggleDay(d)} type="button" style={{
                      padding: "8px 12px", borderRadius: 8, fontSize: 12.5, fontWeight: 600,
                      border: `1px solid ${form.days.includes(d) ? C.teal : C.line}`, background: form.days.includes(d) ? C.tealTint : "#fff", color: form.days.includes(d) ? C.tealDark : C.inkSoft,
                    }}>{d}</button>
                  ))}
                </div>
              </Field>
              <div style={{ fontSize: 11.5, color: C.inkSoft, display: "flex", alignItems: "center", gap: 6 }}>
                <Info size={12} /> You can fine-tune per-day hours, care type, and open ages later in Calendar.
              </div>
            </>
          )}

          {step === 3 && (
            <>
              <Field label="Preferred language">
                <Select value={form.language} onChange={(v) => set("language", v)} options={["English", "Español", "Tagalog", "中文", "Tiếng Việt", "한국어"]} />
              </Field>
              <div style={{ fontSize: 11.5, color: C.inkSoft, display: "flex", alignItems: "center", gap: 6 }}>
                <Info size={12} /> This sets your dashboard language — families you enroll can each have their own preferred language too.
              </div>

              <Field label="Languages offered at your daycare">
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {["English", "Español", "Tagalog", "中文", "Tiếng Việt", "한국어"].map((lang) => (
                    <label key={lang} style={{
                      display: "flex", alignItems: "center", gap: 7, fontSize: 12.5, padding: "7px 11px", borderRadius: 999,
                      border: `1px solid ${form.languagesOffered.includes(lang) ? C.teal : C.line}`,
                      background: form.languagesOffered.includes(lang) ? C.tealTint : "#fff",
                      color: form.languagesOffered.includes(lang) ? C.tealDark : C.inkSoft, fontWeight: 600,
                    }}>
                      <input type="checkbox" checked={form.languagesOffered.includes(lang)} onChange={() => toggleLanguageOffered(lang)} style={{ display: "none" }} />
                      {lang}
                    </label>
                  ))}
                </div>
              </Field>
              <div style={{ fontSize: 11.5, color: C.inkSoft, display: "flex", alignItems: "center", gap: 6 }}>
                <Info size={12} /> Select every language spoken at your daycare — families searching can filter and match by this.
              </div>
            </>
          )}

          {step === 4 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <StatBlock label="Business" value={form.businessName || "—"} />
                <StatBlock label="City" value={form.city || "—"} />
                <StatBlock label="Provider type" value={form.providerType} />
                <StatBlock label="License #" value={form.licenseNumber || "Pending"} />
                <StatBlock label="Capacity" value={String(form.capacity)} />
                <StatBlock label="Age groups" value={form.classrooms.map((c) => classroomOf(c)?.label).join(", ") || "None selected"} />
                <StatBlock label="Hours" value={`${form.hours} · ${form.days.length} days/week`} />
                <StatBlock label="Languages offered" value={form.languagesOffered.join(", ") || "—"} />
              </div>
              <StatBlock label="Subsidy programs" value={form.subsidyPrograms.map((id) => PROGRAMS.find((p) => p.id === id)?.label).join(", ") || "Private-pay only"} />
              <div style={{ fontSize: 12, color: C.inkSoft, display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
                <CheckCircle2 size={13} color={C.teal} /> Everything here can be changed later in Settings and Calendar.
              </div>
              <div style={{ fontSize: 12, color: C.inkSoft, display: "flex", alignItems: "center", gap: 6 }}>
                <Info size={12} /> Have families on paper or in a spreadsheet? Add them from Tours once you're in.
              </div>
            </div>
          )}
        </div>

        <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
          {step > 0 && (
            <button onClick={() => setStep(step - 1)} style={{ flex: 1, padding: "12px 0", borderRadius: 10, border: `1px solid ${C.line}`, background: "#fff", fontWeight: 600, fontSize: 13.5 }}>Back</button>
          )}
          {step < WIZARD_STEPS.length - 1 ? (
            <button onClick={() => canNext() && setStep(step + 1)} disabled={!canNext()} style={{
              flex: 2, padding: "12px 0", borderRadius: 10, border: "none", background: canNext() ? C.teal : "#C9C4B4", color: "#fff", fontWeight: 700, fontSize: 13.5,
              display: "flex", alignItems: "center", justifyContent: "center", gap: 7,
            }}>Continue <ArrowRight size={14} /></button>
          ) : (
            <button onClick={finish} style={{
              flex: 2, padding: "12px 0", borderRadius: 10, border: "none", background: C.amber, color: "#fff", fontWeight: 700, fontSize: 13.5,
              display: "flex", alignItems: "center", justifyContent: "center", gap: 7,
            }}><Rocket size={14} /> Enter your workspace</button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ===================================================================
   PLATFORM ADMIN
   =================================================================== */
function AdminScreen({ onBack }) {
  const [openId, setOpenId] = useState(null);
  const [statusFilter, setStatusFilter] = useState("all");
  const [ADMIN_PROVIDERS, saveAdminProviders] = usePersistentState("admin-providers", ADMIN_PROVIDERS_DEFAULT);
  const [tickets, setTickets] = usePersistentState("support-tickets", SUPPORT_TICKETS_DEFAULT);
  const [openTicketId, setOpenTicketId] = useState(null);
  const openTicket = tickets.find((tk) => tk.id === openTicketId) || null;
  const openTicketCount = tickets.filter((tk) => tk.status === "open").length;
  const toggleTicketStatus = (id) => setTickets(tickets.map((tk) => (tk.id === id ? { ...tk, status: tk.status === "open" ? "resolved" : "open" } : tk)));
  const addTicketReply = (id, text) => {
    const now = new Date();
    setTickets(tickets.map((tk) => (tk.id === id ? { ...tk, replies: [...tk.replies, { from: "support", text, date: now.toLocaleDateString("en-US"), time: now.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" }) }] } : tk)));
  };
  const open = ADMIN_PROVIDERS.find((p) => p.id === openId) || null;

  const mrr = (p) => {
    if (p.status === "canceled") return 0;
    const price = PLAN_PRICING[p.tier];
    return p.cycle === "annual" ? Math.round(price.annual / 12) : price.monthly;
  };
  const totalMRR = ADMIN_PROVIDERS.reduce((s, p) => s + mrr(p), 0);
  const active = ADMIN_PROVIDERS.filter((p) => p.status === "active").length;
  const trial = ADMIN_PROVIDERS.filter((p) => p.status === "trial").length;
  const canceled = ADMIN_PROVIDERS.filter((p) => p.status === "canceled").length;
  const extendedCount = ADMIN_PROVIDERS.filter((p) => p.tier === "extended").length;
  const foundingCount = ADMIN_PROVIDERS.filter((p) => p.founding).length;
  const totalChildren = ADMIN_PROVIDERS.reduce((s, p) => s + p.children, 0);

  const STATUS_META_ADMIN = {
    active: { label: "Active", fg: C.teal, bg: C.tealTint },
    trial: { label: "Trial", fg: C.amber, bg: C.amberTint },
    canceled: { label: "Canceled", fg: C.danger, bg: C.dangerTint },
  };

  const shown = statusFilter === "all" ? ADMIN_PROVIDERS : ADMIN_PROVIDERS.filter((p) => p.status === statusFilter);
  const tierData = [
    { name: "Simple", value: ADMIN_PROVIDERS.filter((p) => p.tier === "simple").length, color: C.sky },
    { name: "Extended", value: extendedCount, color: C.teal },
  ];
  const mrrByProvider = ADMIN_PROVIDERS.map((p) => ({ name: p.name.split(" ").slice(0, 2).join(" "), mrr: mrr(p) })).sort((a, b) => b.mrr - a.mrr);

  // subscription health — computed from real per-provider history, not a decorative number
  const converted = ADMIN_PROVIDERS.filter((p) => p.convertedDate);
  const stillDeciding = ADMIN_PROVIDERS.filter((p) => p.status === "trial");
  const decidedTrials = converted.length + ADMIN_LOST_TRIALS.length;
  const trialConversionRate = decidedTrials ? Math.round((converted.length / decidedTrials) * 100) : 0;
  const paidCanceled = ADMIN_PROVIDERS.filter((p) => p.status === "canceled");
  const churnRate = converted.length ? Math.round((paidCanceled.length / converted.length) * 100) : 0;
  const activePaid = ADMIN_PROVIDERS.filter((p) => p.status === "active" && p.convertedDate);
  const avgTenureMonths = activePaid.length ? Math.round(activePaid.reduce((s, p) => s + tenureMonths(p.convertedDate), 0) / activePaid.length) : 0;

  const MONTHS_2026 = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul"];
  const monthIndex = (dateStr) => Number(dateStr.split("/")[0]) - 1;
  const signupsByMonth = MONTHS_2026.map((m, i) => ({ month: m, signups: ADMIN_PROVIDERS.filter((p) => monthIndex(p.signupDate) === i).length }));
  const mrrByMonth = MONTHS_2026.map((m, i) => {
    const mrrAtMonth = ADMIN_PROVIDERS.reduce((sum, p) => {
      if (!p.convertedDate || monthIndex(p.convertedDate) > i) return sum;
      if (p.canceledDate && monthIndex(p.canceledDate) <= i) return sum;
      return sum + mrr({ ...p, status: "active" });
    }, 0);
    return { month: m, mrr: mrrAtMonth };
  });
  const lostAccounts = [
    ...paidCanceled.map((p) => ({ name: p.name, city: p.city, type: "canceled", date: p.canceledDate, reason: p.cancelReason })),
    ...ADMIN_LOST_TRIALS.map((p) => ({ name: p.name, city: p.city, type: "trial", date: p.lostDate, reason: p.reason })),
  ].sort((a, b) => (a.date < b.date ? 1 : -1));

  return (
    <div style={{ minHeight: "100vh", background: C.cream, fontFamily: "'Work Sans', sans-serif" }}>
      <style>{FONTS}</style>
      <div style={{ background: C.side, borderBottom: `1px solid ${C.line}`, padding: "16px 32px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <AlagaMark size={26} color={C.teal} arch={false} />
          <div>
            <div style={{ fontFamily: "'Fraunces', serif", fontSize: 15, fontWeight: 500, color: C.ink }}><span style={{ fontFamily: "'Fraunces', serif", fontSize: 17, fontWeight: 900 }}>alaga</span> <span style={{ color: C.tealDark, fontWeight: 400 }}>admin</span></div>
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
          <div style={{ position: "relative", display: "flex" }}>
            <LifeBuoy size={19} color={C.inkSoft} />
            {openTicketCount > 0 && (
              <span style={{
                position: "absolute", top: -6, right: -7, minWidth: 16, height: 16, borderRadius: 999, background: C.coral,
                color: "#fff", fontSize: 9.5, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 3px",
              }}>{openTicketCount}</span>
            )}
          </div>
          <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 600, color: C.inkSoft, background: "none", border: `1px solid ${C.line}`, borderRadius: 8, padding: "7px 12px" }}>
            <ArrowLeft size={13} /> Back to start
          </button>
        </div>
      </div>

      {openTicketCount > 0 && (
        <div style={{ background: C.amberTint, borderBottom: `1px solid #E4C77A`, padding: "10px 32px", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
          <LifeBuoy size={14} color="#7A5620" />
          <span style={{ fontSize: 12.5, fontWeight: 700, color: "#7A5620" }}>
            {openTicketCount} open support {openTicketCount === 1 ? "ticket" : "tickets"} awaiting a response
          </span>
        </div>
      )}

      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "28px 32px 60px", display: "flex", flexDirection: "column", gap: 20 }}>
        <div>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 24, fontWeight: 600, color: C.ink }}>Providers on the platform</div>
          <div style={{ fontSize: 13, color: C.inkSoft, marginTop: 3 }}>A cross-account view for the Alaga team — not visible to individual providers.</div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 1fr)", gap: 14 }}>
          <Kpi label="Total providers" value={String(ADMIN_PROVIDERS.length)} sub={`${foundingCount} founding members`} accent={C.teal} />
          <Kpi label="Monthly recurring revenue" value={money(totalMRR)} sub="across all accounts" accent={C.teal} />
          <Kpi label="Active subscriptions" value={String(active)} sub={`${trial} trial · ${canceled} canceled`} accent={active > 0 ? C.teal : C.inkSoft} />
          <Kpi label="On Extended plan" value={`${extendedCount} / ${ADMIN_PROVIDERS.length}`} sub={`${Math.round((extendedCount / ADMIN_PROVIDERS.length) * 100)}% of providers`} accent={C.sky} />
          <Kpi label="Children served platform-wide" value={String(totalChildren)} sub="across active accounts" accent={C.amber} />
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <ChartCard title="Plan mix">
            <ResponsiveContainer width="100%" height={200}>
              <PieChart>
                <Pie data={tierData} dataKey="value" nameKey="name" innerRadius={50} outerRadius={78} paddingAngle={2}>
                  {tierData.map((d, i) => <Cell key={i} fill={d.color} />)}
                </Pie>
                <Tooltip contentStyle={{ fontSize: 12, borderRadius: 8, border: `1px solid ${C.line}` }} />
                <Legend wrapperStyle={{ fontSize: 11.5 }} />
              </PieChart>
            </ResponsiveContainer>
          </ChartCard>
          <ChartCard title="MRR by provider">
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={mrrByProvider} layout="vertical" margin={{ top: 4, right: 16, left: 10, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={C.line} horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 10.5, fill: C.inkSoft }} axisLine={false} tickLine={false} />
                <YAxis type="category" dataKey="name" width={110} tick={{ fontSize: 10.5, fill: C.inkSoft }} axisLine={false} tickLine={false} />
                <Tooltip formatter={(v) => money(v)} contentStyle={{ fontSize: 12, borderRadius: 8, border: `1px solid ${C.line}` }} />
                <Bar dataKey="mrr" fill={C.teal} radius={[0, 6, 6, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </ChartCard>
        </div>

        <div style={{ fontFamily: "'Fraunces', serif", fontSize: 19, fontWeight: 600, color: C.tealDark, marginTop: 4 }}>Subscription health</div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14 }}>
          <Kpi label="Trial conversion rate" value={`${trialConversionRate}%`} sub={`${converted.length} of ${decidedTrials} decided trials`} accent={trialConversionRate >= 60 ? C.teal : C.amber} />
          <Kpi label="Churn rate" value={`${churnRate}%`} sub={`${paidCanceled.length} of ${converted.length} paying accounts`} accent={churnRate > 15 ? C.danger : C.teal} />
          <Kpi label="Still in trial" value={String(stillDeciding.length)} sub="awaiting a decision" accent={C.amber} />
          <Kpi label="Avg. tenure (paying)" value={activePaid.length ? formatTenure(avgTenureMonths) : "—"} sub={`across ${activePaid.length} active accounts`} accent={C.teal} />
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <ChartCard title="Signups by month">
            <ResponsiveContainer width="100%" height={190}>
              <BarChart data={signupsByMonth} margin={{ top: 4, right: 8, left: -18, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={C.line} vertical={false} />
                <XAxis dataKey="month" tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={{ stroke: C.line }} tickLine={false} />
                <YAxis allowDecimals={false} tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={false} tickLine={false} />
                <Tooltip contentStyle={{ fontSize: 12, borderRadius: 8, border: `1px solid ${C.line}` }} />
                <Bar dataKey="signups" fill={C.sky} radius={[6, 6, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </ChartCard>
          <ChartCard title="MRR growth">
            <ResponsiveContainer width="100%" height={190}>
              <LineChart data={mrrByMonth} margin={{ top: 4, right: 12, left: -10, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={C.line} vertical={false} />
                <XAxis dataKey="month" tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={{ stroke: C.line }} tickLine={false} />
                <YAxis tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={false} tickLine={false} tickFormatter={(v) => `$${v}`} />
                <Tooltip formatter={(v) => money(v)} contentStyle={{ fontSize: 12, borderRadius: 8, border: `1px solid ${C.line}` }} />
                <Line type="monotone" dataKey="mrr" stroke={C.teal} strokeWidth={2.5} dot={{ r: 3, fill: C.teal }} />
              </LineChart>
            </ResponsiveContainer>
          </ChartCard>
        </div>

        <Card title="Lost accounts" icon={AlertTriangle} accent={C.amber} right={<span style={{ fontSize: 11, color: C.inkSoft }}>{lostAccounts.length} total — {paidCanceled.length} canceled after paying, {ADMIN_LOST_TRIALS.length} never converted</span>}>
          {lostAccounts.length === 0 && <div style={{ padding: 18, fontSize: 12.5, color: C.inkSoft }}>No lost accounts yet.</div>}
          {lostAccounts.map((a, i) => {
            const reasonLabel = ADMIN_CANCEL_REASONS.find((r) => r.id === a.reason)?.label || a.reason;
            return (
              <Row key={i}
                left={<><Dot c={a.type === "canceled" ? C.danger : C.amber} /><b>{a.name}</b><span style={{ color: C.inkSoft }}>{a.city}</span></>}
                right={<div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <Pill label={a.type === "canceled" ? "Canceled after paying" : "Never converted"} fg={a.type === "canceled" ? C.danger : C.amber} bg={a.type === "canceled" ? C.dangerTint : C.amberTint} />
                  <span style={{ fontSize: 12, color: C.inkSoft, minWidth: 190 }}>{reasonLabel}</span>
                  <span style={{ fontSize: 11.5, color: C.inkSoft }}>{a.date}</span>
                </div>} />
            );
          })}
        </Card>

        <Card title="All providers" icon={Building2}
          right={
            <div style={{ display: "flex", gap: 6 }}>
              {["all", "active", "trial", "canceled"].map((s) => (
                <button key={s} onClick={() => setStatusFilter(s)} style={{
                  padding: "5px 10px", borderRadius: 7, fontSize: 11, fontWeight: 700, textTransform: "capitalize",
                  border: `1px solid ${statusFilter === s ? C.teal : C.line}`, background: statusFilter === s ? C.tealTint : "#fff", color: statusFilter === s ? C.tealDark : C.inkSoft,
                }}>{s}</button>
              ))}
            </div>
          }>
          {shown.map((p) => (
            <button key={p.id} onClick={() => setOpenId(p.id)} style={{ width: "100%", textAlign: "left", background: "none", border: "none", borderRadius: 0, padding: 0 }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 18px", borderBottom: `1px solid ${C.line}` }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
                  <div style={{ width: 34, height: 34, borderRadius: "50%", background: C.tealTint, color: C.tealDark, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 13, flexShrink: 0 }}>{p.name[0]}</div>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 600, display: "flex", alignItems: "center", gap: 6 }}>
                      {p.name} {p.founding && <Pill label="Founding" fg={C.amber} bg={C.amberTint} />}
                    </div>
                    <div style={{ fontSize: 11.5, color: C.inkSoft }}>{p.contact} · {p.city}</div>
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
                  <Pill label={p.tier === "extended" ? "Extended" : "Simple"} fg={p.tier === "extended" ? C.teal : C.sky} bg={p.tier === "extended" ? C.tealTint : C.skyTint} />
                  <Pill {...STATUS_META_ADMIN[p.status]} />
                  <span style={{ fontSize: 12.5, color: C.inkSoft, minWidth: 70, textAlign: "right" }}>{p.children}/{p.capacity} {"children"}</span>
                  <span style={{ fontSize: 13, fontWeight: 700, minWidth: 60, textAlign: "right" }}>{money(mrr(p))}/mo</span>
                  <ChevronRight size={14} color={C.inkSoft} />
                </div>
              </div>
            </button>
          ))}
        </Card>

        <Card title="Support tickets" icon={LifeBuoy} right={<span style={{ fontSize: 12.5, color: C.inkSoft }}>{openTicketCount} open · {tickets.length} total</span>}>
          {tickets.length === 0 && <div style={{ padding: 18, fontSize: 12.5, color: C.inkSoft }}>No support tickets yet.</div>}
          {tickets.map((tk) => (
            <button key={tk.id} onClick={() => setOpenTicketId(tk.id)} style={{ width: "100%", textAlign: "left", background: "none", border: "none", borderRadius: 0, padding: 0 }}>
              <Row
                left={<><Dot c={tk.status === "open" ? C.amber : C.teal} /><b>{tk.subject}</b><span style={{ color: C.inkSoft }}>{tk.provider} · {tk.category}</span></>}
                right={<div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <Pill label={tk.status === "open" ? "Open" : "Resolved"} fg={tk.status === "open" ? C.amber : C.teal} bg={tk.status === "open" ? C.amberTint : C.tealTint} />
                  <span style={{ fontSize: 11.5, color: C.inkSoft }}>{tk.date} · {tk.time}</span>
                  <ChevronRight size={14} color={C.inkSoft} />
                </div>} />
            </button>
          ))}
        </Card>
      </div>

      {open && <AdminProviderDrawer provider={open} mrrValue={mrr(open)} onClose={() => setOpenId(null)} statusMeta={STATUS_META_ADMIN} />}
      {openTicket && <TicketDrawer ticket={openTicket} onClose={() => setOpenTicketId(null)} onToggleStatus={() => toggleTicketStatus(openTicket.id)} onReply={(text) => addTicketReply(openTicket.id, text)} />}
    </div>
  );
}

function AdminProviderDrawer({ provider, mrrValue, onClose, statusMeta }) {
  const [access, saveAccess] = usePersistentState(`support-access-provider-${provider.id}`, SUPPORT_ACCESS_DEFAULT);
  const [viewingSummary, setViewingSummary] = useState(false);
  const isExpired = access.status === "granted" && access.expiresAt && new Date(access.expiresAt) < startOfToday();
  const isActive = access.status === "granted" && !isExpired;

  const requestAccess = () => saveAccess({ ...access, status: "requested", requestedAt: `${todayMDY()} · ${new Date().toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}` });
  const revokeFromAdmin = () => saveAccess({ ...SUPPORT_ACCESS_DEFAULT });
  const viewDashboard = () => {
    saveAccess({ ...access, log: [{ by: "Alaga Support (you)", at: `${todayMDY()} · ${new Date().toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}`, action: "Viewed account summary" }, ...access.log] });
    setViewingSummary(true);
  };

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 60, display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
      <div onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(31,42,36,0.4)" }} />
      <div style={{ position: "relative", width: 560, maxWidth: "94vw", maxHeight: "88vh", background: C.paper, borderRadius: 18, boxShadow: "0 20px 60px rgba(0,0,0,0.25)", display: "flex", flexDirection: "column" }}>
        <div style={{ padding: "22px 24px 18px", borderBottom: `1px solid ${C.line}`, display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
          <div>
            <div style={{ fontFamily: "'Fraunces', serif", fontSize: 19, fontWeight: 600 }}>{provider.name}</div>
            <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 3 }}>{provider.contact} · {provider.city}</div>
            <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
              <Pill label={provider.tier === "extended" ? "Extended" : "Simple"} fg={provider.tier === "extended" ? C.teal : C.sky} bg={provider.tier === "extended" ? C.tealTint : C.skyTint} />
              <Pill {...statusMeta[provider.status]} />
              {provider.founding && <Pill label="Founding member" fg={C.amber} bg={C.amberTint} />}
            </div>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", color: C.inkSoft, padding: 4 }}><X size={19} /></button>
        </div>

        <div style={{ flex: 1, overflowY: "auto", padding: "18px 24px 26px", display: "flex", flexDirection: "column", gap: 18 }}>
          <Section title="Account" icon={Building2}>
            <Row left={<span style={{ color: C.inkSoft }}>Billing cycle</span>} right={<b>{provider.cycle === "annual" ? "Annual" : "Monthly"}</b>} />
            <Row left={<span style={{ color: C.inkSoft }}>MRR</span>} right={<b>{money(mrrValue)}/mo</b>} />
            <Row left={<span style={{ color: C.inkSoft }}>Signed up</span>} right={<b>{provider.signupDate}</b>} />
            <Row left={<span style={{ color: C.inkSoft }}>Last active</span>} right={<b>{provider.lastActive}</b>} />
          </Section>
          <Section title="Enrollment" icon={Users}>
            <Row left={<span style={{ color: C.inkSoft }}>Children enrolled</span>} right={<b>{provider.children} / {provider.capacity}</b>} />
            <Row left={<span style={{ color: C.inkSoft }}>Occupancy</span>} right={<b>{Math.round((provider.children / provider.capacity) * 100)}%</b>} />
          </Section>

          <Section title="Dashboard access" icon={Lock}>
            <div style={{ fontSize: 11.5, color: C.inkSoft, lineHeight: 1.5, marginBottom: 10 }}>
              Admin never sees a provider's live data by default. Access has to be requested, granted by the provider, is time-limited, and every view is logged — visible to them too.
            </div>
            {access.status === "none" && (
              <button onClick={requestAccess} style={{ width: "100%", padding: "10px 0", borderRadius: 9, border: `1px solid ${C.line}`, background: "#fff", fontWeight: 700, fontSize: 12.5, color: C.tealDark }}>
                Request access
              </button>
            )}
            {access.status === "requested" && (
              <div style={{ padding: "10px 12px", borderRadius: 9, background: C.amberTint, color: "#7A5620", fontSize: 12.5 }}>
                Requested {access.requestedAt} — waiting on the provider to approve.
              </div>
            )}
            {access.status === "declined" && (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <div style={{ padding: "10px 12px", borderRadius: 9, background: C.dangerTint, color: C.danger, fontSize: 12.5 }}>Provider declined this request.</div>
                <button onClick={requestAccess} style={{ padding: "9px 0", borderRadius: 9, border: `1px solid ${C.line}`, background: "#fff", fontWeight: 700, fontSize: 12.5, color: C.tealDark }}>Request again</button>
              </div>
            )}
            {isActive && (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <div style={{ padding: "10px 12px", borderRadius: 9, background: C.tealTint, color: C.tealDark, fontSize: 12.5 }}>
                  Granted for {access.durationLabel} — active until {access.expiresAt}.
                </div>
                <button onClick={viewDashboard} style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 7, padding: "10px 0", borderRadius: 9, border: "none", background: C.teal, color: "#fff", fontWeight: 700, fontSize: 12.5 }}>
                  <Eye size={13} /> View account summary
                </button>
                <button onClick={revokeFromAdmin} style={{ fontSize: 11.5, fontWeight: 600, color: C.inkSoft, background: "none", border: "none" }}>End my own access now</button>
              </div>
            )}
            {isExpired && (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <div style={{ padding: "10px 12px", borderRadius: 9, background: "#F1EEE5", color: C.inkSoft, fontSize: 12.5 }}>Access expired {access.expiresAt}.</div>
                <button onClick={requestAccess} style={{ padding: "9px 0", borderRadius: 9, border: `1px solid ${C.line}`, background: "#fff", fontWeight: 700, fontSize: 12.5, color: C.tealDark }}>Request access again</button>
              </div>
            )}
            {viewingSummary && isActive && (
              <div style={{ marginTop: 10, padding: "12px 14px", borderRadius: 10, background: C.cream, border: `1px dashed ${C.line}` }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: C.tealDark, textTransform: "uppercase", letterSpacing: "0.04em", marginBottom: 6 }}>Account summary (read-only)</div>
                <div style={{ fontSize: 12.5, color: C.ink, lineHeight: 1.7 }}>
                  {provider.children}/{provider.capacity} children enrolled · {provider.tier === "extended" ? "Extended" : "Simple"} plan · {money(mrrValue)}/mo
                </div>
                <div style={{ fontSize: 10.5, color: C.inkSoft, marginTop: 6 }}>In production, this opens their actual live dashboard — this demo shows the access grant and logging working end to end.</div>
              </div>
            )}
            {access.log.length > 0 && (
              <div style={{ marginTop: 12 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: C.tealDark, textTransform: "uppercase", letterSpacing: "0.04em", marginBottom: 6 }}>Access log</div>
                {access.log.map((l, i) => (
                  <div key={i} style={{ fontSize: 11.5, color: C.inkSoft, padding: "4px 0" }}>{l.action} · {l.by} · {l.at}</div>
                ))}
              </div>
            )}
          </Section>
        </div>

        <div style={{ padding: "14px 24px", borderTop: `1px solid ${C.line}`, display: "flex", gap: 10 }}>
          <button onClick={onClose} style={{ flex: 1, padding: "10px 0", borderRadius: 10, border: `1px solid ${C.line}`, background: "#fff", fontWeight: 600, fontSize: 13 }}>Close</button>
          <button style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "10px 0", borderRadius: 10, border: "none", background: C.teal, color: "#fff", fontWeight: 600, fontSize: 13 }}>
            <MessageSquare size={13} /> Contact provider
          </button>
        </div>
      </div>
    </div>
  );
}

/* --------------------------- welcome / today's briefing --------------------------- */
// A full-screen "front porch" a provider sees before landing in the dashboard —
// a time-of-day greeting, a weekly encouragement, and a plain-language rundown of
// what actually needs their attention today, all pulled from real workspace data.
const BRIEFING_THEMES = [
  { word: "Steadiness", wordEs: "Estabilidad", line: "Some days move slow. That's not falling behind — that's showing up fully, for every child who needs you to.", lineEs: "Algunos días avanzan despacio. Eso no es quedarse atrás — es estar presente por completo, para cada niño que lo necesita." },
  { word: "Patience", wordEs: "Paciencia", line: "The tantrum, the tears, the tenth question — none of it is too much. You have room for all of it.", lineEs: "La rabieta, las lágrimas, la décima pregunta — nada de eso es demasiado. Tiene espacio para todo eso." },
  { word: "Trust", wordEs: "Confianza", line: "Every family who walks in the door is trusting you with what matters most to them. That trust is earned one ordinary day at a time.", lineEs: "Cada familia que entra por la puerta le confía lo que más les importa. Esa confianza se gana un día ordinario a la vez." },
  { word: "Rest", wordEs: "Descanso", line: "Taking care of yourself isn't separate from taking care of them — it's part of the same job.", lineEs: "Cuidarse a sí misma no está separado de cuidarlos a ellos — es parte del mismo trabajo." },
  { word: "Growth", wordEs: "Crecimiento", line: "The quiet, unglamorous work you do today is exactly what these kids will carry with them.", lineEs: "El trabajo silencioso y poco glamoroso que hace hoy es exactamente lo que estos niños llevarán consigo." },
  { word: "Community", wordEs: "Comunidad", line: "You're not just running a daycare — you're holding a small piece of your neighborhood together.", lineEs: "No solo dirige una guardería — mantiene unida una pequeña parte de su vecindario." },
  { word: "Presence", wordEs: "Presencia", line: "You don't have to get today perfect. You just have to be there for it.", lineEs: "No tiene que hacer que hoy sea perfecto. Solo tiene que estar presente." },
  { word: "Warmth", wordEs: "Calidez", line: "A steady, familiar face at the door is worth more to a small child than almost anything else.", lineEs: "Una cara conocida y constante en la puerta vale más para un niño pequeño que casi cualquier otra cosa." },
];
function isoWeekNumber(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function WelcomeBriefing({ providerInfo, families, staff, prospects, threads, flexCareRequests, dismissedNotices, isEmpty, onEnter, language, reminderSettings, closures = [], licensing = {}, compDocs = [] }) {
  const now = new Date();
  const hour = now.getHours();
  const greetWord = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
  const greetWordEs = hour < 12 ? "Buenos días" : hour < 17 ? "Buenas tardes" : "Buenas noches";
  const firstName = (providerInfo.contactName || providerInfo.name || "there").split(" ")[0];
  const dateLabel = now.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });
  const theme = BRIEFING_THEMES[isoWeekNumber(now) % BRIEFING_THEMES.length];

  const subsidizedFams = families.filter((f) => f.subsidized);
  const expiring = subsidizedFams.filter((f) => f.status !== "active" && !dismissedNotices.includes(f.id));
  const pendingFlex = flexCareRequests.filter((r) => r.status === "pending");
  const unpaidFlex = flexCareRequests.filter((r) => r.status === "approved" && !r.paymentConfirmed);
  const unreadThreads = threads.filter((th) => th.unread);
  const toursScheduled = prospects.filter((p) => p.stage === "Tour Scheduled");
  const missingCerts = staff.filter((s) => Object.values(s.certs || {}).some((v) => v === "missing"));

  // Each item carries a JSX version for display plus plain English/Spanish
  // sentences for text-to-speech, since spoken items can't read the JSX.
  const items = [];
  const plain = (tone, en, es) => items.push({ tone, text: en, textEs: es, speechEn: en, speechEs: es });
  const es = (str) => (T[str] && T[str].es) || str;
  const noop = () => {};
  // Same overdue / due-today list the dashboard shows, so the two always agree.
  briefingDueItems({ closures, prospects, families, licensing, reminderSettings, t: (x) => x, go: { calendar: noop, tours: noop, family: noop, compliance: noop, tuition: noop } })
    .filter((it) => it.n <= 0)
    .forEach((it) => { const said = /overdue|today/i.test(it.detail); plain("urgent", `${it.title} — ${it.detail}${said ? "" : it.n < 0 ? " (overdue)" : " (today)"}.`, `${it.title} — ${es(it.detail)}${said ? "" : it.n < 0 ? " (atrasado)" : " (hoy)"}.`); });
  const billingNow = reminderSettings ? currentBilling(reminderSettings) : null;
  const overdueTuition = billingNow && billingNow.overdue ? families.filter((f) => f.copay > 0 && !paidFor(f, billingNow.key)) : [];
  if (overdueTuition.length > 0) plain("urgent",
    `${overdueTuition.length} ${overdueTuition.length === 1 ? "family is" : "families are"} past due on ${billingNow.label} tuition.`,
    `${overdueTuition.length} ${overdueTuition.length === 1 ? "familia tiene" : "familias tienen"} la colegiatura de ${billingNow.label} vencida.`);
  const docsDue = compDocs.filter((d) => (d.displayStatus || d.status) !== "submitted").length;
  const childDocsDue = families.filter((f) => defaultChildDocs(f).some((d) => d.status === "missing" || ["expired", "expiring"].includes(docEffectiveStatus(d, 30)))).length;
  if (docsDue + childDocsDue > 0) plain("warn",
    [docsDue ? `${docsDue} business ${docsDue === 1 ? "document" : "documents"}` : "", childDocsDue ? `${childDocsDue} ${childDocsDue === 1 ? "child's record" : "children's records"}` : ""].filter(Boolean).join(" and ") + " need updating.",
    [docsDue ? `${docsDue} ${docsDue === 1 ? "documento del negocio" : "documentos del negocio"}` : "", childDocsDue ? `${childDocsDue} ${childDocsDue === 1 ? "expediente de niño" : "expedientes de niños"}` : ""].filter(Boolean).join(" y ") + " necesitan actualizarse.");
  if (families.length > 0) {
    items.push({
      tone: "ok", text: <>You have <strong>{families.length}</strong> {families.length === 1 ? "child" : "children"} in your care — <strong>{subsidizedFams.length}</strong> subsidized and <strong>{families.length - subsidizedFams.length}</strong> private-pay.</>,
      textEs: <>Tiene <strong>{families.length}</strong> {families.length === 1 ? "niño" : "niños"} bajo su cuidado — <strong>{subsidizedFams.length}</strong> con subsidio y <strong>{families.length - subsidizedFams.length}</strong> de pago privado.</>,
      speechEn: `You have ${families.length} ${families.length === 1 ? "child" : "children"} in your care — ${subsidizedFams.length} subsidized and ${families.length - subsidizedFams.length} private-pay.`,
      speechEs: `Tiene ${families.length} ${families.length === 1 ? "niño" : "niños"} bajo su cuidado — ${subsidizedFams.length} con subsidio y ${families.length - subsidizedFams.length} de pago privado.`,
    });
  }
  if (expiring.length > 0) {
    items.push({
      tone: "warn", text: <><strong>{expiring.length}</strong> subsidy {expiring.length === 1 ? "authorization needs" : "authorizations need"} your attention.</>,
      textEs: <><strong>{expiring.length}</strong> {expiring.length === 1 ? "autorización de subsidio necesita" : "autorizaciones de subsidio necesitan"} su atención.</>,
      speechEn: `${expiring.length} subsidy ${expiring.length === 1 ? "authorization needs" : "authorizations need"} your attention.`,
      speechEs: `${expiring.length} ${expiring.length === 1 ? "autorización de subsidio necesita" : "autorizaciones de subsidio necesitan"} su atención.`,
    });
  }
  if (pendingFlex.length + unpaidFlex.length > 0) {
    items.push({
      tone: "warn", text: <><strong>{pendingFlex.length + unpaidFlex.length}</strong> flex care {pendingFlex.length + unpaidFlex.length === 1 ? "request needs" : "requests need"} approval or payment confirmation.</>,
      textEs: <><strong>{pendingFlex.length + unpaidFlex.length}</strong> {pendingFlex.length + unpaidFlex.length === 1 ? "solicitud de cuidado flexible necesita" : "solicitudes de cuidado flexible necesitan"} aprobación o confirmación de pago.</>,
      speechEn: `${pendingFlex.length + unpaidFlex.length} flex care ${pendingFlex.length + unpaidFlex.length === 1 ? "request needs" : "requests need"} approval or payment confirmation.`,
      speechEs: `${pendingFlex.length + unpaidFlex.length} ${pendingFlex.length + unpaidFlex.length === 1 ? "solicitud de cuidado flexible necesita" : "solicitudes de cuidado flexible necesitan"} aprobación o confirmación de pago.`,
    });
  }
  if (toursScheduled.length > 0) {
    items.push({
      tone: "ok", text: <>You have <strong>{toursScheduled.length}</strong> {toursScheduled.length === 1 ? "tour" : "tours"} on the calendar — {toursScheduled.map((p) => p.name).join(", ")}.</>,
      textEs: <>Tiene <strong>{toursScheduled.length}</strong> {toursScheduled.length === 1 ? "recorrido" : "recorridos"} en el calendario — {toursScheduled.map((p) => p.name).join(", ")}.</>,
      speechEn: `You have ${toursScheduled.length} ${toursScheduled.length === 1 ? "tour" : "tours"} on the calendar — ${toursScheduled.map((p) => p.name).join(", ")}.`,
      speechEs: `Tiene ${toursScheduled.length} ${toursScheduled.length === 1 ? "recorrido" : "recorridos"} en el calendario — ${toursScheduled.map((p) => p.name).join(", ")}.`,
    });
  }
  if (unreadThreads.length > 0) {
    items.push({
      tone: "msg", text: <><strong>{unreadThreads.length}</strong> unread {unreadThreads.length === 1 ? "message" : "messages"} from families.</>,
      textEs: <><strong>{unreadThreads.length}</strong> {unreadThreads.length === 1 ? "mensaje sin leer" : "mensajes sin leer"} de familias.</>,
      speechEn: `${unreadThreads.length} unread ${unreadThreads.length === 1 ? "message" : "messages"} from families.`,
      speechEs: `${unreadThreads.length} ${unreadThreads.length === 1 ? "mensaje sin leer" : "mensajes sin leer"} de familias.`,
    });
  }
  if (missingCerts.length > 0) {
    items.push({
      tone: "warn", text: <><strong>{missingCerts.map((s) => s.name).join(", ")}</strong> {missingCerts.length === 1 ? "has" : "have"} a certification on file that still needs to be completed.</>,
      textEs: <><strong>{missingCerts.map((s) => s.name).join(", ")}</strong> {missingCerts.length === 1 ? "tiene" : "tienen"} una certificación pendiente de completar.</>,
      speechEn: `${missingCerts.map((s) => s.name).join(", ")} ${missingCerts.length === 1 ? "has" : "have"} a certification on file that still needs to be completed.`,
      speechEs: `${missingCerts.map((s) => s.name).join(", ")} ${missingCerts.length === 1 ? "tiene" : "tienen"} una certificación pendiente de completar.`,
    });
  }
  if (items.length === 0) {
    const okEn = isEmpty ? "No families enrolled yet — once they join, your daily rundown will show up here." : "Nothing urgent today — a good day to get ahead on paperwork.";
    const okEs = isEmpty ? "Aún no hay familias inscritas — cuando se unan, su resumen diario aparecerá aquí." : "Nada urgente hoy — un buen día para adelantar papeleo.";
    items.push({ tone: "ok", text: okEn, textEs: okEs, speechEn: okEn, speechEs: okEs });
  }
  // Urgency first: anything needing action (warn), then messages, then good-news items.
  const urgencyRank = { urgent: 0, warn: 1, msg: 2, ok: 3 };
  items.sort((a, b) => urgencyRank[a.tone] - urgencyRank[b.tone]);
  // Keep the morning view short: the three most urgent things, the rest wait on the dashboard.
  const moreCount = Math.max(0, items.length - 3);
  items.splice(3);

  // Text-to-speech mockup — English and Spanish only, matching the provider's
  // dashboard language when it's one of those two; real speech synthesis via
  // the browser, no backend needed.
  const [briefLang, setBriefLang] = useState(language === "Español" ? "es" : "en");
  const speechLang = briefLang;
  const [speaking, setSpeaking] = useState(false);
  const speakBriefing = () => {
    if (!window.speechSynthesis) return;
    if (speaking) { window.speechSynthesis.cancel(); setSpeaking(false); return; }
    const isEs = speechLang === "es";
    const greeting = isEs ? `${greetWordEs}, ${firstName}.` : `${greetWord}, ${firstName}.`;
    const body = items.map((it) => (isEs ? it.speechEs : it.speechEn)).join(" ");
    const utterance = new SpeechSynthesisUtterance(`${greeting} ${body}`);
    // es-US (neutral, broadly-understood Latin American Spanish) fits this
    // audience better than es-ES, and needs a slower rate than English to
    // sound natural rather than rushed.
    utterance.lang = isEs ? "es-US" : "en-US";
    utterance.rate = isEs ? 0.85 : 0.98;
    if (isEs && window.speechSynthesis.getVoices) {
      const voices = window.speechSynthesis.getVoices();
      const preferred = voices.find((v) => /es-US|es-MX|es-419/i.test(v.lang))
        || voices.find((v) => v.lang.toLowerCase().startsWith("es"));
      if (preferred) utterance.voice = preferred;
    }
    utterance.onend = () => setSpeaking(false);
    utterance.onerror = () => setSpeaking(false);
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
    setSpeaking(true);
  };
  const ttsSupported = typeof window !== "undefined" && !!window.speechSynthesis;
  const isEs = briefLang === "es";
  const dateLabelLocalized = isEs
    ? now.toLocaleDateString("es-ES", { weekday: "long", month: "long", day: "numeric" })
    : dateLabel;

  const toneColor = { ok: C.teal, warn: C.amber, msg: C.sky, urgent: C.danger };

  return (
    <div style={{
      minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center",
      padding: "48px 20px", background: `radial-gradient(ellipse 900px 500px at 15% 0%, #FFFDF8 0%, transparent 60%), ${C.cream}`,
      fontFamily: "'Work Sans', sans-serif",
    }}>
      <style>{FONTS}</style>
      <div style={{ width: "100%", maxWidth: 760 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 32 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <AlagaMark size={44} color={C.tealDark} arch backdrop={false} />
            <div style={{ fontSize: 13, letterSpacing: "0.08em", textTransform: "uppercase", color: C.teal, fontWeight: 700 }}>alaga · provider workspace</div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
            <div style={{ display: "flex", gap: 2, padding: 3, borderRadius: 999, border: `1px solid ${C.line}`, background: "#fff" }}>
              {[["en", "English"], ["es", "Español"]].map(([code, label]) => (
                <button key={code} onClick={() => setBriefLang(code)} style={{
                  padding: "6px 13px", borderRadius: 999, border: "none", fontSize: 12, fontWeight: 700,
                  background: briefLang === code ? C.tealDark : "transparent", color: briefLang === code ? "#fff" : C.inkSoft,
                }}>{label}</button>
              ))}
            </div>
            {ttsSupported && (
              <button onClick={speakBriefing} title={speaking ? "Stop reading" : "Listen to today's briefing"} style={{
                display: "flex", alignItems: "center", gap: 7, padding: "8px 14px", borderRadius: 999,
                border: `1px solid ${speaking ? C.teal : C.line}`, background: speaking ? C.tealTint : "#fff",
                color: speaking ? C.tealDark : C.inkSoft, fontSize: 12.5, fontWeight: 700, flexShrink: 0,
              }}>
                {speaking ? <><Square size={12} fill={C.tealDark} /> {isEs ? "Detener" : "Stop"}</> : <><Volume2 size={14} /> {isEs ? "Escuchar" : "Listen"}</>}
              </button>
            )}
          </div>
        </div>

        <div style={{ fontFamily: "'Fraunces', serif", fontOpticalSizing: "auto", fontWeight: 500, fontSize: 46, lineHeight: 1.15, color: C.ink, marginBottom: 8 }}>
          {isEs ? greetWordEs : greetWord}, {firstName}
        </div>
        <div style={{ fontSize: 15, color: C.inkSoft, marginBottom: 32 }}>
          {dateLabelLocalized} · {providerInfo.name}{providerInfo.city ? `, ${providerInfo.city}` : ""}
        </div>

        <div style={{ position: "relative", borderRadius: 16, overflow: "hidden", marginBottom: 22, border: `1px solid ${C.line}`, background: C.paper }}>
          <div style={{ padding: "13px 20px", fontSize: 12, fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase", color: C.inkSoft, borderBottom: `1px solid ${C.line}` }}>
            {isEs ? "Hoy, de un vistazo — lo más urgente primero" : "Today, at a glance — most urgent first"}
          </div>
          <div>
            {items.map((it, i) => (
              <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "16px 20px", borderBottom: i < items.length - 1 || moreCount ? `1px solid ${C.line}` : "none" }}>
                <Dot c={toneColor[it.tone]} />
                <div style={{ fontSize: 15, color: C.ink, lineHeight: 1.5 }}>{isEs ? it.textEs : it.text}</div>
              </div>
            ))}
            {moreCount > 0 && (
              <div style={{ padding: "12px 20px", fontSize: 13.5, color: C.inkSoft }}>
                {isEs ? `Y ${moreCount} ${moreCount === 1 ? "cosa más" : "cosas más"} en tu panel.` : `Plus ${moreCount} more ${moreCount === 1 ? "thing" : "things"} on your dashboard.`}
              </div>
            )}
          </div>
        </div>

        <div style={{ display: "flex", alignItems: "flex-start", gap: 12, marginBottom: 22, padding: "16px 20px", background: C.tealTint, borderRadius: 16 }}>
          <Sparkles size={18} color={C.teal} style={{ flexShrink: 0, marginTop: 3 }} />
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, letterSpacing: "0.05em", textTransform: "uppercase", color: C.teal, marginBottom: 4 }}>{isEs ? "Esta semana" : "This week"}: {isEs ? theme.wordEs : theme.word}</div>
            <p style={{ fontFamily: "'Fraunces', serif", fontStyle: "italic", fontSize: 16.5, lineHeight: 1.5, color: C.tealDark }}>{isEs ? theme.lineEs : theme.line}</p>
          </div>
        </div>

        <button onClick={onEnter} style={{
          width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          padding: "15px 20px", borderRadius: 12, border: "none", background: C.teal, color: "#fff",
          fontWeight: 700, fontSize: 15.5, marginBottom: 10,
        }}>
          {isEs ? "Comenzar el día" : "Step into the day"} <ArrowRight size={16} />
        </button>
      </div>
    </div>
  );
}

function Workspace({ initialLanguage = "English", onLanguageChange, isEmpty, providerInfo: initialProviderInfo, onboardingData, onExitToLanding, forceTier, meetingMode = false, startInParentMode = false }) {
  const sfx = isEmpty ? "-empty" : "";
  const [providerInfo, saveProviderInfo] = usePersistentState(`provider-profile${sfx}`, {
    name: initialProviderInfo.name, city: initialProviderInfo.city, lic: initialProviderInfo.lic,
    providerType: initialProviderInfo.providerType || PROVIDER_TYPES[0], capacity: initialProviderInfo.capacity || 8,
    contactName: initialProviderInfo.contactName || "", email: initialProviderInfo.email || "",
    languagesOffered: initialProviderInfo.languagesOffered || ["English"],
    subsidyPrograms: initialProviderInfo.subsidyPrograms || [],
  });
  const baseFamilies = isEmpty ? [] : FAMILIES.map(withDemoPayments);
  const baseProspects = isEmpty ? [] : PROSPECTIVE_FAMILIES_DEFAULT;
  const baseExpenses = isEmpty ? [] : EXPENSES_DEFAULT;
  const baseCompDocsRaw = isEmpty ? COMPLIANCE_DOCS.map((d) => ({ ...d, status: "missing", date: undefined })) : COMPLIANCE_DOCS;
  const baseThreads = isEmpty ? [] : MESSAGE_THREADS;

  // Families enrolled through the app (from Tours or the Waitlist). The sample
  // daycare's families come from built-in data; these are the provider's own.
  const [addedFamilies, saveAddedFamilies] = usePersistentState(`added-families${sfx}`, []);
  const [enrollingProspectId, setEnrollingProspectId] = useState(null);
  const [mode, setMode] = useState(startInParentMode ? "parent" : "provider"); // "provider" | "parent"
  // Providers land on the welcome briefing every time they open the workspace —
  // it's a front porch, not a one-time onboarding step.
  // The welcome screen shows once a day; later visits go straight to the dashboard.
  const welcomeKey = `alaga-welcome-seen${isEmpty ? "-empty" : ""}`;
  // The greeting, weekly note and Listen button now live at the top of the
  // dashboard, so there's no separate welcome screen to click through.
  const [showBriefing, setShowBriefing] = useState(false);
  const enterWorkspace = () => { try { localStorage.setItem(welcomeKey, todayMDY()); } catch (e) { /* private mode */ } setShowBriefing(false); };
  const [screen, setScreenRaw] = useState("dashboard");
  const [screenHistory, setScreenHistory] = useState([]);
  // navigateToScreen replaces plain setScreen everywhere a nav happens, so the
  // provider can always retrace their steps instead of hunting for where they were.
  const navigateToScreen = useCallback((next) => {
    setScreenRaw((current) => {
      if (current !== next) setScreenHistory((h) => [...h, current]);
      return next;
    });
  }, []);
  const canGoBack = screenHistory.length > 0;
  const goBack = useCallback(() => {
    setScreenHistory((h) => {
      if (h.length === 0) return h;
      const prev = h[h.length - 1];
      setScreenRaw(prev);
      return h.slice(0, -1);
    });
  }, []);
  const setScreen = navigateToScreen;
  const [settingsTab, setSettingsTab] = useState("profile");
  const [messageToast, setMessageToast] = useState(null);
  const isMobile = useIsMobile();
  const [navOpen, setNavOpen] = useState(false);
  const [supportTab, setSupportTab] = useState("help");
  const [openFamId, setOpenFamId] = useState(null);
  const [openHousehold, setOpenHousehold] = useState(null);
  const [flexHighlightId, setFlexHighlightId] = useState(null);
  const [financesTab, setFinancesTab] = useState("tuition");
  // From the dashboard's Today's briefing, jump straight into the specific
  // family's subsidy record or flex care request instead of the general screen.
  const goToSubsidyFamily = useCallback((famId) => {
    setOpenFamId(famId);
    navigateToScreen("subsidy");
  }, [navigateToScreen]);
  const goToFlexRequest = useCallback((reqId) => {
    setFlexHighlightId(reqId);
    navigateToScreen("bookings");
  }, [navigateToScreen]);
  // Search results for a specific child/family jump straight to their record in
  // the Families directory rather than dropping the provider into the full list.
  const goToFamily = useCallback((famId) => {
    const match = [...(isEmpty ? [] : FAMILIES), ...addedFamilies].find((f) => f.id === famId);
    if (match) setOpenHousehold(match.household);
    navigateToScreen("families");
  }, [isEmpty, addedFamilies, navigateToScreen]);
  const [overrides, setOverrides] = useState({});
  const [loaded, setLoaded] = useState(false);
  // Saved on this device, so the chosen language stays until it's changed.
  const [language, saveLanguage] = usePersistentState(`app-language${sfx}`, onboardingData?.language || initialLanguage);
  // One choice everywhere: changing it here also sets the start and sign-in screens.
  const setLanguage = (l) => { saveLanguage(l); onLanguageChange && onLanguageChange(l); };
  const [tier, saveTier] = usePersistentState(forceTier ? `platform-tier-demo-${forceTier}` : "platform-tier", forceTier || "simple");
  const tierLocked = !!forceTier;
  const [billing, saveBilling] = usePersistentState(`plan-billing${sfx}`, { cycle: "monthly", status: "active", canceledAt: null, startedOn: todayMDY() });
  const [payrollSettings, savePayrollSettings] = usePersistentState(`payroll-settings${sfx}`, { frequency: "Biweekly", nextPayDate: shiftDemoString("08/07/2026"), providerConnected: false, providerName: "" });
  const [flexCareRequests, saveFlexCare] = usePersistentState(`flex-care${sfx}`, isEmpty ? [] : FLEX_CARE_DEFAULT);
  const [refunds, saveRefunds] = usePersistentState(`refunds${sfx}`, isEmpty ? [] : REFUNDS_DEFAULT);
  const [attendanceLog, saveAttendanceLog] = usePersistentState(`attendance${sfx}`, {});
  const [tuitionRates, saveTuitionRates] = usePersistentState(`tuition-rates${sfx}`, TUITION_RATES_DEFAULT);

  useEffect(() => {
    if (tier === "simple" && NAV.find((n) => n.id === screen)?.extended) setScreen("dashboard");
  }, [tier]);
  const [checkStatus, setCheckStatus] = useState(() => Object.fromEntries(baseFamilies.map((f, i) => [
    f.id, i % 3 === 0 ? { status: "out", time: null } : { status: "in", time: ["7:42 AM", "8:05 AM", "7:58 AM", "8:11 AM"][i % 4] },
  ])));
  const [checkLog, setCheckLog] = useState([]);
  const [accessLog, setAccessLog] = useState([]);
  const initialSchedule = isEmpty && onboardingData
    ? ALL_DAYS.map((d) => ({
        day: d, open: onboardingData.days.includes(d), hours: onboardingData.hours, careType: "Full-day",
        capacity: onboardingData.capacity || 8, ages: onboardingData.classrooms?.map((c) => classroomOf(c)?.label).filter(Boolean).join(", ") || "",
        ageClassrooms: onboardingData.classrooms || [],
      }))
    : WEEKLY_SCHEDULE_DEFAULT;
  const [weeklySchedule, saveWeeklySchedule] = usePersistentState(`calendar-weekly${sfx}`, initialSchedule);
  const [careSchedules, saveCareSchedules] = usePersistentState(`care-schedules${sfx}`, DEFAULT_CARE_SCHEDULES);
  ACTIVE_CARE_SCHEDULES = careSchedules.length ? careSchedules : DEFAULT_CARE_SCHEDULES;
  const [closures, saveClosures] = usePersistentState(`calendar-closures${sfx}`, isEmpty ? [] : PACKET_CLOSURES.map((c, i) => {
    const [start, end] = c.dates.split(" – ");
    return { id: `pc${i}`, name: c.name, dates: c.dates, start, end: end || start, fromPacket: true, notified: true };
  }));
  const [events, saveEvents] = usePersistentState(`calendar-events${sfx}`, isEmpty ? [] : CALENDAR_EVENTS_DEFAULT);
  const [prospects, saveProspects] = usePersistentState(`tours-pipeline${sfx}`, baseProspects);
  const [compOverrides, saveCompOverrides] = usePersistentState(`compliance-docs${sfx}`, {});
  const [incidents, saveIncidents] = usePersistentState(`incident-reports${sfx}`, []);
  // The provider's own licensing record (renewal, last inspection). Sample values in the demo only.
  const [licensing, saveLicensing] = usePersistentState(`licensing${sfx}`, isEmpty
    ? { renewalDate: "", inspectionDate: "", inspectionResult: "", citations: "" }
    : demoDates({ renewalDate: "03/31/2027", inspectionDate: "04/12/2026", inspectionResult: "No citations", citations: "" }));
  const [mandatedNotes, saveMandatedNotes] = usePersistentState(`mandated-reporting-notes${sfx}`, []);
  const [expenses, saveExpenses] = usePersistentState(`business-expenses${sfx}`, baseExpenses);
  const [budgetPlan, saveBudgetPlan] = usePersistentState(`budget-plan${sfx}`, BUDGET_PLAN_DEFAULT);
  // Your own daily routine. Things Alaga already tracks (subsidies, messages,
  // paperwork) show in the briefing instead, so they aren't repeated here.
  const [checklist, saveChecklist] = usePersistentState(`daily-checklist-v2${sfx}`, [
    { id: 1, text: "Put out the sign-in sheet", done: false },
    { id: 2, text: "Restock hand-washing & sanitizing supplies", done: false },
    { id: 3, text: "Prep afternoon snack", done: false },
    { id: 4, text: "Wipe down tables and toys", done: false },
  ]);
  const [dismissedNotices, saveDismissedNotices] = usePersistentState(`dismissed-notices${sfx}`, []);
  const [a11y, saveA11y] = usePersistentState("accessibility-settings", { dark: false, highContrast: false, textSize: 16, reducedMotion: false });
  const [reminderSettings, saveReminderSettings] = usePersistentState("invoice-reminders", { enabled: true, daysBefore: 7, lateFeeEnabled: false, lateFeeType: "flat", lateFeeAmount: 25, lateFeePercent: 5, forceLateFee: false });
  const [growth, saveGrowth] = usePersistentState(`growth-assessment${sfx}`, { started: false, targetCapacity: 12, targetStaff: 1, timeline: "6–12 months", checklist: [], notes: "" });
  const [staff, saveStaff] = usePersistentState(`staff${sfx}`, isEmpty ? [] : STAFF_DEFAULT);
  const [alumni, saveAlumni] = usePersistentState(`alumni${sfx}`, isEmpty ? [] : ALUMNI_DEFAULT);
  const addDeparture = useCallback((entry) => {
    alumniSeq += 1;
    saveAlumni([{ id: `a${alumniSeq}`, ...entry }, ...alumni]);
  }, [alumni, saveAlumni]);
  const [threads, saveThreads] = useState(baseThreads);

  const setChildStatus = useCallback((f, next, reason = null) => {
    const time = new Date().toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
    setCheckStatus((s) => ({ ...s, [f.id]: { status: next, time, reason: next === "out" ? reason : null } }));
    setCheckLog((l) => [{ id: `${f.id}-${l.length}-${Date.now()}`, child: f.child, color: f.color, action: next, time, reason: next === "out" ? reason : null }, ...l].slice(0, 12));
  }, []);

  const logAccess = useCallback((kind, label) => {
    setAccessLog((l) => [{ id: `${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, kind, label, time: "just now" }, ...l].slice(0, 25));
  }, []);

  // load any previously saved subsidy edits on mount
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const next = {};
      for (const f of baseFamilies) {
        try {
          const res = await window.storage.get(storageKey(f.id));
          if (res && res.value) next[f.id] = JSON.parse(res.value);
        } catch (e) {
          // no saved override yet for this family — fine, use defaults
        }
      }
      if (!cancelled) { setOverrides(next); setLoaded(true); }
    })();
    return () => { cancelled = true; };
  }, []);

  const saveOverride = useCallback(async (famId, fields) => {
    if (addedFamilies.some((f) => f.id === famId)) {
      return saveAddedFamilies(addedFamilies.map((f) => (f.id === famId ? { ...f, ...fields } : f)));
    }
    const merged = { ...(overrides[famId] || {}), ...fields };
    setOverrides((o) => ({ ...o, [famId]: merged }));
    try {
      await window.storage.set(storageKey(famId), JSON.stringify(merged));
      return true;
    } catch (e) {
      return false;
    }
  }, [overrides, addedFamilies, saveAddedFamilies]);
  // leftDate = null undoes a withdrawal and removes its departure entry.
  const withdrawChild = useCallback(async (child, leftDate, reason) => {
    if (!leftDate) {
      saveAlumni(alumni.filter((a) => a.familyId !== child.id));
      return saveOverride(child.id, { departedOn: null, departureReason: null });
    }
    addDeparture({ name: child.child, classroom: child.classroom, enrollDate: child.enrollDate, leftDate, reason, familyId: child.id });
    return saveOverride(child.id, { departedOn: leftDate, departureReason: reason });
  }, [alumni, saveAlumni, addDeparture, saveOverride]);

  const saveCompDoc = useCallback(async (docId, fields) => {
    const merged = { ...(compOverrides[docId] || {}), ...fields };
    const next = { ...compOverrides, [docId]: merged };
    return saveCompOverrides(next);
  }, [compOverrides, saveCompOverrides]);

  const updateProspect = useCallback((id, fields) => {
    saveProspects(prospects.map((p) => {
      if (p.id !== id) return p;
      const joiningWaitlist = fields.stage === "Waitlist" && p.stage !== "Waitlist";
      const stageChanged = fields.stage && fields.stage !== p.stage;
      return { ...p, ...fields, ...(stageChanged ? { stageSince: todayMDY() } : {}), ...(joiningWaitlist ? { waitlistedOn: todayMDY(), waitlistedAt: Date.now() } : {}) };
    }));
  }, [prospects, saveProspects]);
  // Turning a tour family into enrolled children: creates one family record per
  // child (sharing a household), marks the tour as Enrolled, and opens the record.
  const enrollProspect = useCallback(async (prospect, records) => {
    await saveAddedFamilies([...addedFamilies, ...records]);
    saveProspects(prospects.map((p) => (p.id === prospect.id ? { ...p, stage: "Enrolled", familyIds: records.map((r) => r.id) } : p)));
    setEnrollingProspectId(null);
    setOpenHousehold(records[0].household);
    navigateToScreen("families");
  }, [addedFamilies, saveAddedFamilies, prospects, saveProspects, navigateToScreen]);
  const addProspect = useCallback(() => {
    tourSeq += 1;
    saveProspects([{ id: `t${tourSeq}`, name: "New family", stage: "Inquiry", tourDate: "Not scheduled", careType: "Full-time", children: "Not entered", start: "Not entered", language: "English", contact: "", email: "", notes: "", followup: "", addedOn: todayMDY() }, ...prospects]);
  }, [prospects, saveProspects]);
  const removeProspect = useCallback((id) => {
    saveProspects(prospects.filter((p) => p.id !== id));
  }, [prospects, saveProspects]);

  const updateStaffMember = useCallback((id, fields) => {
    saveStaff(staff.map((s) => (s.id === id ? { ...s, ...fields } : s)));
  }, [staff, saveStaff]);
  const addStaffMember = useCallback(() => {
    staffSeq += 1;
    saveStaff([{ id: staffSeq, name: "New staff member", role: STAFF_ROLES[1], classroom: "all", hireDate: todayMDY().replace(/\/\d{2}\//, "/"), hoursPerWeek: 20, payType: "hourly", payRate: 18, status: "active", certs: { livescan: "missing", cpr: "missing", health: "missing", ece: "missing", mandated: "missing" } }, ...staff]);
  }, [staff, saveStaff]);
  const removeStaffMember = useCallback((id) => {
    saveStaff(staff.filter((s) => s.id !== id));
  }, [staff, saveStaff]);

  // A withdrawn child stays on the roster through their last day, then moves to Deenrolled.
  const families = [...baseFamilies, ...addedFamilies].map((f) => mergeFam(f, overrides))
    .filter((f) => !(f.departedOn && daysUntil(f.departedOn) < 0))
    .map((f) => (f.subsidized ? { ...f, status: subsidyStatus(f) } : f));
  const subsidizedFamsForBadge = families.filter((f) => f.subsidized);
  const expiringCount = subsidizedFamsForBadge.filter((f) => f.status !== "active" && !dismissedNotices.includes(f.id)).length;
  const unreadMessagesCount = threads.filter((th) => th.unread).length;
  // New message alerts: an in-app notice, plus a browser notification when the
  // provider has allowed them. (Alerts while Alaga is closed need the backend.)
  const [messageAlerts, saveMessageAlerts] = usePersistentState(`message-alerts${sfx}`, true);
  const incomingCount = threads.reduce((n, th) => n + th.messages.filter((m) => m.from !== "me").length, 0);
  const incomingRef = React.useRef({ count: null, since: Date.now() });
  useEffect(() => {
    const r = incomingRef.current;
    if (r.count !== null && incomingCount > r.count && Date.now() - r.since > 1500) {
      const th = [...threads].sort((a, b) => threadLastAt(b) - threadLastAt(a)).find((x) => x.unread) || threads[0];
      const last = th?.messages[th.messages.length - 1];
      if (th && messageAlerts) {
        setMessageToast({ name: th.name, text: last?.text || "" });
        if (typeof Notification !== "undefined" && Notification.permission === "granted") new Notification(`New message from ${th.name}`, { body: last?.text || "" });
      }
    }
    r.count = incomingCount;
  }, [incomingCount]);
  const flexAttentionCount = flexCareRequests.filter((r) => r.status === "pending" || (r.status === "approved" && !r.paymentConfirmed)).length;
  // Jump to a screen (and a tab on Finances, Settings or Support).
  const goTo = (target) => {
    if (!target) return;
    if (target.screen === "payments" && target.tab) setFinancesTab(target.tab);
    if (target.screen === "settings" && target.tab) setSettingsTab(target.tab);
    if (target.screen === "support") setSupportTab(target.tab || "help");
    setScreen(target.screen);
  };
  const navItems = NAV.filter((n) => tier === "extended" || !n.extended).map((n) => {
    if (n.id === "subsidy") return { ...n, badge: expiringCount > 0 ? expiringCount : undefined };
    if (n.id === "messages") return { ...n, badge: unreadMessagesCount > 0 ? unreadMessagesCount : undefined };
    if (n.id === "bookings") return { ...n, badge: flexAttentionCount > 0 ? flexAttentionCount : undefined };
    if (n.id === "waitlist") { const wc = prospects.filter((p) => p.stage === "Waitlist").length; return { ...n, badge: wc > 0 ? wc : undefined }; }
    return n;
  });
  const compDocs = baseCompDocsRaw.map((d) => {
    const merged = { ...d, ...(compOverrides[d.id] || {}) };
    const withExpiry = { ...merged, expiresOn: merged.expiresOn ?? expiryFromText(merged.date) };
    return { ...withExpiry, displayStatus: docEffectiveStatus(withExpiry) };
  });
  const openFam = families.find((f) => f.id === openFamId) || null;
  const langCode = LANG_CODES[language] || "en";
  const t = useCallback((s) => (langCode === "en" ? plainEnglish(s) : (T[s] && T[s][langCode]) || s), [langCode]);

  const a11yCSS = `
    .a11y-scale { zoom: ${(a11y.textSize / 16).toFixed(3)}; }
    ${a11y.highContrast ? ".a11y-scale { filter: contrast(1.35) saturate(1.15); }" : ""}
    ${a11y.dark ? ".a11y-scale { filter: invert(0.93) hue-rotate(180deg); } .a11y-scale img { filter: invert(1) hue-rotate(180deg); }" : ""}
    ${a11y.reducedMotion ? ".a11y-scale * { transition: none !important; animation: none !important; }" : ""}
  `;

  if (showBriefing) {
    return (
      <LanguageContext.Provider value={{ lang: langCode, t }}>
        <WelcomeBriefing
          providerInfo={providerInfo}
          families={families}
          staff={staff}
          prospects={prospects}
          threads={threads}
          flexCareRequests={flexCareRequests}
          dismissedNotices={dismissedNotices}
          isEmpty={isEmpty}
          language={language}
          reminderSettings={reminderSettings}
          closures={closures}
          licensing={licensing}
          compDocs={compDocs}
          onEnter={enterWorkspace}
        />
      </LanguageContext.Provider>
    );
  }

  return (
    <LanguageContext.Provider value={{ lang: langCode, t }}>
    <div className="a11y-scale" style={{ display: "flex", minHeight: "100vh", background: C.cream, fontFamily: "'Work Sans', sans-serif", color: C.ink }}>
      <style>{FONTS}{a11yCSS}{`
        * { box-sizing: border-box; }
        button { font-family: inherit; cursor: pointer; }
        ::-webkit-scrollbar { width: 8px; height: 8px; }
        ::-webkit-scrollbar-thumb { background: ${C.line}; border-radius: 8px; }
      `}</style>

      {mode === "provider" ? (
        <>
          {!isMobile && <Sidebar screen={screen} setScreen={setScreen} mode={mode} setMode={setMode} provider={providerInfo} onExitToLanding={onExitToLanding} isEmpty={isEmpty} navItems={navItems} tier={tier} saveTier={saveTier} tierLocked={tierLocked} meetingMode={meetingMode} financesTab={financesTab} setFinancesTab={setFinancesTab} />}
          {isMobile && navOpen && (
            <div style={{ position: "fixed", inset: 0, zIndex: 90, display: "flex" }}>
              <div style={{ height: "100%", overflowY: "auto", display: "flex", boxShadow: "4px 0 24px rgba(0,0,0,0.15)" }}>
                <Sidebar screen={screen} setScreen={(id) => { setScreen(id); setNavOpen(false); }} mode={mode} setMode={setMode} provider={providerInfo} onExitToLanding={onExitToLanding} isEmpty={isEmpty} navItems={navItems} tier={tier} saveTier={saveTier} tierLocked={tierLocked} meetingMode={meetingMode} financesTab={financesTab} setFinancesTab={(tb) => { setFinancesTab(tb); setNavOpen(false); }} />
              </div>
              <div onClick={() => setNavOpen(false)} style={{ flex: 1, background: "rgba(31,42,36,0.35)" }} />
            </div>
          )}
          <main style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
            <Topbar screen={screen} setScreen={setScreen} provider={providerInfo} families={families} staff={staff} goBack={goBack} canGoBack={canGoBack} goToFamily={goToFamily} goTo={goTo} available={navItems.map((n) => n.id)} isMobile={isMobile} onMenu={() => setNavOpen(true)} unread={unreadMessagesCount} language={language} setLanguage={setLanguage} />
            <div className="alaga-main" style={{ flex: 1, overflowY: "auto", padding: "28px 32px 60px" }}>
              {screen === "dashboard" && <Dashboard setScreen={setScreen} goToFamily={goToFamily} reminderSettings={reminderSettings} openTuition={() => { setFinancesTab("tuition"); setScreen("payments"); }} families={families} checklist={checklist} saveChecklist={saveChecklist} dismissedNotices={dismissedNotices} saveDismissedNotices={saveDismissedNotices} tuitionRates={tuitionRates} saveTuitionRates={saveTuitionRates} weeklySchedule={weeklySchedule} staff={staff} prospects={prospects} compDocs={compDocs} providerInfo={providerInfo} flexCareRequests={flexCareRequests} saveFlexCare={saveFlexCare} goToSubsidyFamily={goToSubsidyFamily} goToFlexRequest={goToFlexRequest} meetingMode={meetingMode} events={events} closures={closures} licensing={licensing} goToTour={() => setScreen("tours")} attendanceLog={attendanceLog} />}
              {FEATURES.checkin && screen === "checkin" && <CheckIn families={families} status={checkStatus} log={checkLog} setChildStatus={setChildStatus} />}
              {screen === "families" && <Families families={families} provider={providerInfo} onWithdraw={withdrawChild} openTuition={() => { setFinancesTab("tuition"); setScreen("payments"); }} goToSubsidy={(id) => { setScreen("subsidy"); setOpenFamId(id); }} onSave={saveOverride} logAccess={logAccess} setScreen={setScreen} openHousehold={openHousehold} setOpenHousehold={setOpenHousehold} tuitionRates={tuitionRates} alumni={alumni} />}
              {screen === "bookings" && <Bookings families={families} schedule={fullWeek(weeklySchedule)} closures={closures} provider={providerInfo} staff={staff} tuitionRates={tuitionRates} flexCareRequests={flexCareRequests} saveFlexCare={saveFlexCare} attendanceLog={attendanceLog} saveAttendanceLog={saveAttendanceLog} onSave={saveOverride} highlightId={flexHighlightId} />}
              {screen === "staff" && <StaffScreen staff={staff} families={families} updateStaffMember={updateStaffMember} addStaffMember={addStaffMember} removeStaffMember={removeStaffMember} />}
              {screen === "calendar" && <CalendarScreen careSchedules={careSchedules} saveCareSchedules={saveCareSchedules} schedule={fullWeek(weeklySchedule)} saveSchedule={saveWeeklySchedule} closures={closures} saveClosures={saveClosures} events={events} saveEvents={saveEvents} families={families} threads={threads} saveThreads={saveThreads} />}
              {screen === "tours" && <ToursScreen providerInfo={providerInfo} prospects={prospects} updateProspect={updateProspect} addProspect={addProspect} removeProspect={removeProspect} logAccess={logAccess} startEnroll={(p) => setEnrollingProspectId(p.id)} />}
              {screen === "waitlist" && <WaitlistScreen prospects={prospects} updateProspect={updateProspect} removeProspect={removeProspect} logAccess={logAccess} families={families} providerInfo={providerInfo} startEnroll={(p) => setEnrollingProspectId(p.id)} />}
              {screen === "subsidy" && <Subsidy families={families} openFamId={openFamId} setOpenFamId={setOpenFamId} loaded={loaded} meetingMode={meetingMode} />}
              {screen === "payments" && <Finances careCtx={{ attendanceLog, schedule: fullWeek(weeklySchedule), closures }} families={families} expenses={expenses} saveExpenses={saveExpenses} reminderSettings={reminderSettings} saveReminderSettings={saveReminderSettings} staff={staff} tier={tier} payrollSettings={payrollSettings} savePayrollSettings={savePayrollSettings} onSave={saveOverride} refunds={refunds} saveRefunds={saveRefunds} flexCareRequests={flexCareRequests} tuitionRates={tuitionRates} saveTuitionRates={saveTuitionRates} setScreen={setScreen} providerInfo={providerInfo} meetingMode={meetingMode} budgetPlan={budgetPlan} saveBudgetPlan={saveBudgetPlan} activeTab={financesTab} setActiveTab={setFinancesTab} />}
              {screen === "compliance" && <Compliance licensing={licensing} saveLicensing={saveLicensing} docs={compDocs} onSave={saveCompDoc} families={families} provider={providerInfo} staff={staff} setScreen={setScreen} incidents={incidents} saveIncidents={saveIncidents} mandatedNotes={mandatedNotes} saveMandatedNotes={saveMandatedNotes} />}
              {screen === "security" && <SecurityScreen accessLog={accessLog} isEmpty={isEmpty} />}
              {screen === "messages" && <Messages isMobile={isMobile} threads={threads} saveThreads={saveThreads} families={families} staff={staff} goToFamily={goToFamily} openSupport={() => setScreen("support")} alertsOn={messageAlerts} setAlertsOn={saveMessageAlerts} />}
              {screen === "analytics" && <Analytics families={families} expenses={expenses} prospects={prospects} staff={staff} alumni={alumni} addDeparture={addDeparture} refunds={refunds} flexCareRequests={flexCareRequests} tuitionRates={tuitionRates} setScreen={(id, opts) => { if (opts?.tab) setSettingsTab(opts.tab); setScreen(id); }} provider={providerInfo} />}
              {screen === "growth" && <GrowthScreen families={families} prospects={prospects} weeklySchedule={weeklySchedule} growth={growth} saveGrowth={saveGrowth} provider={providerInfo} staff={staff} />}
              {screen === "support" && <SupportScreen providerInfo={providerInfo} goTo={goTo} available={navItems.map((n) => n.id)} tab={supportTab} setTab={setSupportTab} />}
              {screen === "settings" && <SettingsScreen tab={settingsTab} setTab={setSettingsTab} language={language} setLanguage={setLanguage} a11y={a11y} saveA11y={saveA11y} tier={tier} saveTier={saveTier} tierLocked={tierLocked} meetingMode={meetingMode} billing={billing} saveBilling={saveBilling} families={families} staff={staff} expenses={expenses} compDocs={compDocs} provider={providerInfo} saveProviderInfo={saveProviderInfo} refunds={refunds}
                exportCtx={{ provider: providerInfo, licensing, families, allFamilies: [...baseFamilies, ...addedFamilies].map((f) => mergeFam(f, overrides)), alumni, staff, attendanceLog, schedule: fullWeek(weeklySchedule), closures, compDocs, incidents, expenses, refunds, threads, prospects }}
                threads={threads} saveThreads={saveThreads} isDemo={!isEmpty || !!forceTier || meetingMode} onSignOut={onExitToLanding} />}
            </div>
          </main>
          {messageToast && screen !== "messages" && (
            <div style={{ position: "fixed", right: 20, bottom: 20, zIndex: 70, width: 320, background: C.paper, border: `1px solid ${C.line}`, borderRadius: 14, boxShadow: "0 12px 32px rgba(0,0,0,0.18)", padding: "12px 14px", display: "flex", gap: 10 }}>
              <MessageSquare size={18} color={C.teal} style={{ flexShrink: 0, marginTop: 2 }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12.5, fontWeight: 700 }}>{messageToast.name}</div>
                <div style={{ fontSize: 12, color: C.inkSoft, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{messageToast.text}</div>
                <button onClick={() => { setMessageToast(null); setScreen("messages"); }} style={{ marginTop: 6, fontSize: 12, fontWeight: 700, color: C.teal, background: "none", border: "none", padding: 0 }}>Open messages</button>
              </div>
              <button onClick={() => setMessageToast(null)} style={{ background: "none", border: "none", color: C.inkSoft, alignSelf: "flex-start" }}><X size={14} /></button>
            </div>
          )}
          {screen === "subsidy" && openFam && (
            <SubsidyDrawer fam={openFam} onClose={() => setOpenFamId(null)} onSave={saveOverride} logAccess={logAccess} />
          )}
          {enrollingProspectId && prospects.find((p) => p.id === enrollingProspectId) && (
            <EnrollModal
              prospect={prospects.find((p) => p.id === enrollingProspectId)}
              providerInfo={providerInfo}
              tuitionRates={tuitionRates}
              onCancel={() => setEnrollingProspectId(null)}
              onEnroll={enrollProspect}
            />
          )}
        </>
      ) : (
        <ParentApp careCtx={{ attendanceLog, schedule: fullWeek(weeklySchedule), closures }} families={families} onExit={() => (startInParentMode ? (onExitToLanding && onExitToLanding()) : setMode("provider"))} showBackToProvider={!startInParentMode} status={checkStatus} setChildStatus={setChildStatus} provider={providerInfo} onSave={saveOverride} flexCareRequests={flexCareRequests} saveFlexCare={saveFlexCare} tuitionRates={tuitionRates} threads={threads} saveThreads={saveThreads} refunds={refunds} language={language} setLanguage={setLanguage} events={events} reminderSettings={reminderSettings} />
      )}
    </div>
    </LanguageContext.Provider>
  );
}

export default function AlagaMockup() {
  const [entry, setEntry] = useState("landing"); // "landing" | "wizard" | "workspace" | "admin"
  const [isEmptyWorkspace, setIsEmptyWorkspace] = useState(false);
  const [forcedTier, setForcedTier] = useState(null);
  const [meetingMode, setMeetingMode] = useState(false);
  const [startInParent, setStartInParent] = useState(false);
  const [providerInfo, setProviderInfo] = useState(PROVIDER);
  const [onboardingData, setOnboardingData] = useState(null);
  const [authMode, setAuthMode] = useState("signin");
  const [publicLanguage, setPublicLanguage] = usePersistentState("app-language-public", detectLanguage());
  const tPublic = makeT(publicLanguage);
  const publicCtx = { lang: LANG_CODES[publicLanguage] || "en", t: tPublic };
  const [signupEmail, setSignupEmail] = useState("");

  const registerWithAdmin = async (info) => {
    try {
      const key = "admin-providers";
      let list = ADMIN_PROVIDERS_DEFAULT;
      try {
        const res = await window.storage.get(key);
        if (res && res.value) list = JSON.parse(res.value);
      } catch (e) { /* nothing saved yet — start from the default cohort */ }
      const foundingCount = list.filter((p) => p.founding).length;
      const today = new Date().toLocaleDateString("en-US", { month: "2-digit", day: "2-digit", year: "numeric" });
      const newEntry = {
        id: Date.now(),
        name: info.name || "New Provider",
        contact: info.contactName || "—",
        city: info.city || "—",
        tier: "simple",
        status: "trial",
        cycle: "monthly",
        children: 0,
        capacity: info.capacity || 8,
        signupDate: today,
        convertedDate: null,
        lastActive: today,
        founding: foundingCount < 100,
      };
      await window.storage.set(key, JSON.stringify([newEntry, ...list]));
    } catch (e) { /* admin registration is best-effort — never block the actual signup on it */ }
  };

  if (entry === "landing") {
    return <LanguageContext.Provider value={publicCtx}><LandingChooser language={publicLanguage} setLanguage={setPublicLanguage}
      onDemo={(demoTier, isMeeting) => { setProviderInfo(PROVIDER); setIsEmptyWorkspace(false); setOnboardingData(null); setForcedTier(demoTier); setMeetingMode(!!isMeeting); setStartInParent(false); setEntry("workspace"); }}
      onSignUp={() => { setAuthMode("signup"); setEntry("auth"); }}
      onAdmin={() => setEntry("admin")}
      onSignIn={() => { setAuthMode("signin"); setEntry("auth"); }}
      onParentDemo={() => { setProviderInfo(PROVIDER); setIsEmptyWorkspace(false); setOnboardingData(null); setForcedTier("extended"); setMeetingMode(false); setStartInParent(true); setEntry("workspace"); }}
    /></LanguageContext.Provider>;
  }
  if (entry === "auth") {
    // Real Firebase accounts. A brand-new account goes straight into the setup
    // wizard. Signing in to an existing account drops into the populated demo
    // workspace until the backend + Cloud SQL wiring can load each provider's own data.
    return <LanguageContext.Provider value={publicCtx}><LoginScreen language={publicLanguage} setLanguage={setPublicLanguage}
      key={authMode}
      initialMode={authMode}
      onAuthenticated={(user, mode) => {
        if (mode === "signup") { setSignupEmail(user?.email || ""); setEntry("wizard"); return; }
        setProviderInfo(PROVIDER); setIsEmptyWorkspace(false); setOnboardingData(null); setForcedTier(null); setMeetingMode(false); setEntry("workspace");
      }}
      onBack={() => setEntry("landing")}
    /></LanguageContext.Provider>;
  }
  if (entry === "admin") {
    return <LanguageContext.Provider value={{ lang: "en", t: (s) => s }}><AdminScreen onBack={() => setEntry("landing")} /></LanguageContext.Provider>;
  }
  if (entry === "wizard") {
    return <LanguageContext.Provider value={{ lang: "en", t: (s) => s }}><OnboardingWizard
      initialEmail={signupEmail}
      onComplete={(info) => { setProviderInfo(info); setOnboardingData(info); registerWithAdmin(info); setIsEmptyWorkspace(true); setForcedTier(null); setMeetingMode(false); setEntry("workspace"); }}
      onBack={() => setEntry("landing")}
    /></LanguageContext.Provider>;
  }
  return <Workspace initialLanguage={publicLanguage} onLanguageChange={setPublicLanguage} isEmpty={isEmptyWorkspace} providerInfo={providerInfo} onboardingData={onboardingData} onExitToLanding={() => setEntry("landing")} forceTier={forcedTier} meetingMode={meetingMode} startInParentMode={startInParent} />;
}

/* --------------------------------- sidebar ------------------------------------ */
function Sidebar({ screen, setScreen, mode, setMode, provider, onExitToLanding, isEmpty, navItems, tier, saveTier, tierLocked, meetingMode = false, financesTab, setFinancesTab }) {
  const t = useT();
  const [expandedGroups, setExpandedGroups] = useState({});
  return (
    <aside style={{
      width: 232, flexShrink: 0, background: C.side, color: C.ink, display: "flex", flexDirection: "column", padding: "22px 14px",
      borderRight: `1px solid ${C.line}`,
    }}>
      {onExitToLanding && (
        <button onClick={onExitToLanding} style={{
          display: "flex", alignItems: "center", gap: 7, alignSelf: "flex-start",
          padding: "6px 10px 6px 8px", borderRadius: 8, border: `1px solid ${C.line}`, background: "transparent",
          color: C.inkSoft, fontSize: 11.5, fontWeight: 600, marginBottom: 12,
        }}>
          <ArrowLeft size={12} /> {t("Back to start")}
        </button>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "4px 8px 22px" }}>
        <AlagaMark size={30} color={C.ink} arch={false} />
        <div>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 20, fontWeight: 900, lineHeight: 1 }}>alaga</div>
          <div style={{ fontSize: 8.5, letterSpacing: "0.14em", textTransform: "uppercase", color: C.inkSoft, marginTop: 4 }}>{t("Nurturing the foundation for your childcare business")}</div>
        </div>
      </div>

      {tierLocked ? (
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "7px 0",
          borderRadius: 9, background: "#fff", margin: "0 0 14px", fontSize: 11.5, fontWeight: 700, color: C.ink,
        }}>
          {meetingMode ? <><Lock size={11} /> {t("Meeting-safe demo")}</> : (tier === "extended" ? t("Extended plan demo") : t("Simple plan demo"))}
        </div>
      ) : (
        // Shows the current plan only; changing plans happens in Settings → Plan & Billing.
        <button onClick={() => setScreen("settings")} title={t("Change plan in Settings")} style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "7px 0", width: "100%",
          borderRadius: 9, border: "none", background: "#fff", margin: "0 0 14px", fontSize: 11.5, fontWeight: 700, color: C.ink,
        }}>
          {tier === "extended" ? t("Extended plan") : t("Simple plan")} <ChevronRight size={12} style={{ opacity: 0.7 }} />
        </button>
      )}

      {isEmpty && (
        <div style={{ margin: "0 10px 14px", padding: "8px 10px", borderRadius: 9, background: "rgba(224,169,80,0.18)", border: "1px solid rgba(224,169,80,0.35)" }}>
          <div style={{ fontSize: 10.5, fontWeight: 700, color: C.amber, textTransform: "uppercase", letterSpacing: "0.04em" }}>{t("New workspace")}</div>
          <div style={{ fontSize: 11, color: C.ink, marginTop: 2, lineHeight: 1.4 }}>{t("Empty preview — nothing here is real data yet.")}</div>
        </div>
      )}

      <div style={{ fontSize: 10.5, letterSpacing: "0.08em", textTransform: "uppercase", color: C.inkSoft, padding: "0 10px 6px" }}>{t("Workspace")}</div>
      <nav style={{ display: "flex", flexDirection: "column", gap: 2 }}>
        {(() => {
          const renderedGroups = new Set();
          return navItems.map((n) => {
            const owningGroup = NAV_GROUPS.find((g) => g.children.some((c) => c.id === n.id));
            if (owningGroup) {
              if (renderedGroups.has(owningGroup.id)) return null;
              renderedGroups.add(owningGroup.id);
              const visibleChildren = owningGroup.children.filter((c) => tier === "extended" || !c.extended);
              const groupActive = visibleChildren.some((c) => c.id === screen);
              const isExpanded = expandedGroups[owningGroup.id] !== undefined ? expandedGroups[owningGroup.id] : groupActive;
              const groupBadge = visibleChildren.reduce((sum, c) => {
                const src = navItems.find((x) => x.id === c.id);
                return sum + (typeof src?.badge === "number" ? src.badge : 0);
              }, 0);
              return (
                <div key={owningGroup.id}>
                  <button onClick={() => setExpandedGroups((g) => ({ ...g, [owningGroup.id]: !isExpanded }))} style={{
                    width: "100%", display: "flex", alignItems: "center", gap: 10, padding: "9px 10px", borderRadius: 9,
                    border: "none", background: groupActive && !isExpanded ? C.tealTint : "transparent",
                    color: groupActive ? C.tealDark : C.inkSoft, fontSize: 13.5, fontWeight: groupActive ? 600 : 500, textAlign: "left",
                  }}>
                    <owningGroup.icon size={16} strokeWidth={2} />
                    <span style={{ flex: 1 }}>{t(owningGroup.label)}</span>
                    {groupBadge > 0 && !isExpanded && <span style={{ background: C.coral, color: "#fff", fontSize: 10.5, fontWeight: 700, borderRadius: 999, padding: "1px 6px" }}>{groupBadge}</span>}
                    <ChevronDown size={13} style={{ transform: isExpanded ? "none" : "rotate(-90deg)", transition: "transform 0.12s", flexShrink: 0, opacity: 0.7 }} />
                  </button>
                  {isExpanded && (
                    <div style={{ display: "flex", flexDirection: "column", gap: 1, margin: "2px 0 4px", marginLeft: 15, paddingLeft: 11, borderLeft: `1px solid ${C.line}` }}>
                      {visibleChildren.map((c) => {
                        const childOn = screen === c.id && (!c.tab || financesTab === c.tab);
                        const src = navItems.find((x) => x.id === c.id);
                        return (
                          <button key={c.id + (c.tab || "")} onClick={() => { setScreen(c.id); if (c.tab && setFinancesTab) setFinancesTab(c.tab); }} style={{
                            display: "flex", alignItems: "center", gap: 8, padding: "7px 9px", borderRadius: 8,
                            border: "none", background: childOn ? C.tealTint : "transparent",
                            color: childOn ? C.tealDark : C.inkSoft, fontSize: 12.5, fontWeight: childOn ? 600 : 500, textAlign: "left",
                          }}>
                            <span style={{ flex: 1 }}>{t(c.label)}</span>
                            {src?.badge && (!c.tab) && <span style={{ background: C.coral, color: "#fff", fontSize: 10, fontWeight: 700, borderRadius: 999, padding: "1px 5px" }}>{src.badge}</span>}
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            }
            const on = screen === n.id;
            return (
              <button key={n.id} onClick={() => setScreen(n.id)} style={{
                display: "flex", alignItems: "center", gap: 10, padding: "9px 10px", borderRadius: 9,
                border: "none", background: on ? C.tealTint : "transparent",
                color: on ? C.tealDark : C.inkSoft, fontSize: 13.5, fontWeight: on ? 600 : 500, textAlign: "left",
              }}>
                <n.icon size={16} strokeWidth={2} />
                <span style={{ flex: 1 }}>{t(n.label)}</span>
                {n.badge && <span style={{ background: C.coral, color: "#fff", fontSize: 10.5, fontWeight: 700, borderRadius: 999, padding: "1px 6px" }}>{n.badge}</span>}
              </button>
            );
          });
        })()}
      </nav>

      {false && setMode && (
        <button onClick={() => setMode("parent")} style={{
          display: "flex", alignItems: "center", gap: 10, padding: "9px 10px", borderRadius: 9, marginTop: 10,
          border: `1px solid ${C.line}`, background: "transparent", color: C.inkSoft, fontSize: 13, fontWeight: 600, textAlign: "left",
        }}>
          <Users size={15} strokeWidth={2} />
          <span style={{ flex: 1 }}>{t("View as parent")}</span>
          <ArrowRight size={13} />
        </button>
      )}

      <div style={{ marginTop: "auto", paddingTop: 14, borderTop: `1px solid ${C.line}` }}>
        <div style={{ fontSize: 12 }}>
          <div style={{ fontWeight: 600, color: C.ink }}>{provider.name}</div>
          <div style={{ color: C.inkSoft, marginTop: 2 }}>{provider.city}</div>
          <div style={{ color: C.inkSoft, marginTop: 1, fontSize: 11 }}>{provider.lic}</div>
        </div>
      </div>
    </aside>
  );
}

function Topbar({ screen, setScreen, provider, families, staff, goBack, canGoBack, goToFamily, goTo, available, isMobile = false, onMenu, unread = 0, language, setLanguage }) {
  const t = useT();
  const title = NAV.find((n) => n.id === screen)?.label || "";
  // Reflects the real current date whenever the page loads/refreshes.
  const [todayLabel] = useState(() => new Date().toLocaleDateString(undefined, { weekday: "long", year: "numeric", month: "long", day: "numeric" }));
  const [query, setQuery] = useState("");
  const [focused, setFocused] = useState(false);
  const [helpOpen, setHelpOpen] = useState(null);
  const q = query.trim().toLowerCase();

  // Exact / near-exact match on a single family or child jumps straight to that
  // record instead of dropping the provider into the full directory.
  const householdMatches = families.filter((f) => f.householdName.toLowerCase().includes(q) || f.child.toLowerCase().includes(q));
  const exactSingleMatch = q.length >= 3 && householdMatches.length === 1 ? householdMatches[0] : null;

  // Match on the child's name or the family (household) name, so typing "Reyes"
  // surfaces the Reyes children right in the dropdown instead of only on Enter.
  const results = q.length === 0 ? [] : [
    ...householdMatches.slice(0, 5).map((f) => ({ label: f.child, sub: `${f.householdName} · ${t("Families")}`, icon: Users, screen: "families", famId: f.id })),
    ...staff.filter((s) => s.name.toLowerCase().includes(q)).slice(0, 5).map((s) => ({ label: s.name, sub: `${t(s.role)} · ${t("Staff & Ratios")}`, icon: UserCog, screen: "staff" })),
    ...BLANK_FORMS.filter((f) => f.name.toLowerCase().includes(q)).slice(0, 3).map((f) => ({ label: f.name, sub: t("Blank forms & templates"), icon: FileText, screen: "compliance" })),
    ...searchHelp(q, t).filter((h) => !available || available.includes(h.go.screen)).map((h) => ({ label: t(h.q), sub: `${t("How do I…")} · ${t(h.cat)}`, icon: LifeBuoy, help: h })),
  ];

  const selectResult = (r) => {
    if (r.help) { setHelpOpen(r.help); setQuery(""); setFocused(false); return; }
    if (r.famId && goToFamily) goToFamily(r.famId);
    else setScreen(r.screen);
    setQuery(""); setFocused(false);
  };

  const handleEnter = (e) => {
    if (e.key === "Enter" && exactSingleMatch && goToFamily) {
      goToFamily(exactSingleMatch.id);
      setQuery(""); setFocused(false);
    }
  };

  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: isMobile ? "wrap" : "nowrap", rowGap: 10, padding: isMobile ? "10px 14px" : "18px 32px", borderBottom: `1px solid ${C.line}`, background: C.paper, position: isMobile ? "sticky" : "static", top: 0, zIndex: 30 }}>
      <div style={{ display: "flex", alignItems: "center", gap: isMobile ? 10 : 14, minWidth: 0 }}>
        {isMobile && onMenu && (
          <button onClick={onMenu} aria-label={t("Menu")} style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center", width: 38, height: 38, borderRadius: 10, border: `1px solid ${C.line}`, background: "#fff", color: C.ink, flexShrink: 0 }}>
            <Menu size={18} />
            {unread > 0 && <span style={{ position: "absolute", top: -4, right: -4, background: C.coral, color: "#fff", fontSize: 10, fontWeight: 700, borderRadius: 999, padding: "1px 5px" }}>{unread}</span>}
          </button>
        )}
        {canGoBack && (
          <button onClick={goBack} title={t("Back")} style={{
            display: "flex", alignItems: "center", justifyContent: "center", width: 32, height: 32, borderRadius: 9,
            border: `1px solid ${C.line}`, background: "#fff", color: C.ink, flexShrink: 0,
          }}>
            <ArrowLeft size={15} />
          </button>
        )}
        <div>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: isMobile ? 19 : 22, fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{t(title)}</div>
          {!isMobile && <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 2 }}>{todayLabel}</div>}
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14, order: isMobile ? 3 : 0, width: isMobile ? "100%" : "auto" }}>
        <div style={{ position: "relative", flex: isMobile ? 1 : "none" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, border: `1px solid ${focused ? C.teal : C.line}`, borderRadius: 10, padding: "7px 12px", color: C.inkSoft, fontSize: 13, width: isMobile ? "100%" : 280 }}>
            <Search size={14} style={{ flexShrink: 0 }} />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onFocus={() => setFocused(true)}
              onBlur={() => setTimeout(() => setFocused(false), 150)}
              onKeyDown={handleEnter}
              placeholder={t("Search, or ask how to do something…")}
              style={{ border: "none", outline: "none", background: "none", fontSize: 13, width: "100%", fontFamily: "inherit", color: C.ink }}
            />
            {query && (
              <button onClick={() => setQuery("")} style={{ background: "none", border: "none", color: C.inkSoft, display: "flex", flexShrink: 0 }}><X size={13} /></button>
            )}
          </div>
          {focused && q.length > 0 && (
            <div style={{
              position: "absolute", top: "calc(100% + 6px)", left: 0, right: 0, background: "#fff",
              border: `1px solid ${C.line}`, borderRadius: 10, boxShadow: "0 8px 24px rgba(0,0,0,0.1)", zIndex: 60,
              maxHeight: 360, overflowY: "auto", width: isMobile ? "100%" : 340,
            }}>
              {results.length === 0 ? (
                <div style={{ padding: "14px 16px", fontSize: 12.5, color: C.inkSoft }}>{t("No matches for")} "{query}". <button onMouseDown={() => { goTo && goTo({ screen: "support", tab: "help" }); setQuery(""); }} style={{ background: "none", border: "none", padding: 0, color: C.teal, fontWeight: 700, fontSize: 12.5 }}>{t("Browse all help")}</button></div>
              ) : results.map((r, i) => (
                <button key={i} onMouseDown={() => selectResult(r)} style={{
                  width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: 10, padding: "10px 14px",
                  background: "none", border: "none", borderBottom: i < results.length - 1 ? `1px solid ${C.line}` : "none",
                }}>
                  <r.icon size={14} color={C.teal} style={{ flexShrink: 0 }} />
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.label}</div>
                    <div style={{ fontSize: 11, color: C.inkSoft }}>{r.sub}</div>
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>
        {helpOpen && (
          <div style={{ position: "fixed", inset: 0, zIndex: 80, display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
            <div onClick={() => setHelpOpen(null)} style={{ position: "absolute", inset: 0, background: "rgba(31,42,36,0.35)" }} />
            <div style={{ position: "relative", width: 460, maxWidth: "94vw", background: C.paper, borderRadius: 16, boxShadow: "0 20px 50px rgba(0,0,0,0.2)", padding: "18px 22px 20px" }}>
              <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10, marginBottom: 12 }}>
                <div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: C.tealDark, textTransform: "uppercase", letterSpacing: "0.04em" }}>{t("How do I…")}</div>
                  <div style={{ fontFamily: "'Fraunces', serif", fontSize: 18, fontWeight: 600, marginTop: 2 }}>{t(helpOpen.q)}</div>
                </div>
                <button onClick={() => setHelpOpen(null)} style={{ background: "none", border: "none", color: C.inkSoft }}><X size={18} /></button>
              </div>
              <HelpAnswer topic={helpOpen} goTo={goTo} onDone={() => setHelpOpen(null)} />
              <button onClick={() => { goTo && goTo({ screen: "support", tab: "help" }); setHelpOpen(null); }} style={{ marginTop: 12, background: "none", border: "none", padding: 0, fontSize: 12, fontWeight: 700, color: C.inkSoft }}>{t("Browse all help")} →</button>
            </div>
          </div>
        )}
        {setLanguage && <LanguagePicker language={language} setLanguage={setLanguage} compact />}
        <div style={{ width: 34, height: 34, borderRadius: "50%", background: C.tealTint, color: C.tealDark, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 13 }} title={provider?.contactName || provider?.name}>{initialsOf(provider?.contactName || provider?.name)}</div>
      </div>
    </div>
  );
}

